export const BODY = {"level-3":{"id":"level-3","kind":"level","level":3,"src":"level:3","title":"Level 3 · The Column Road","body":"Three-digit column sums and mental shortcuts, the nine and twelve times tables, equivalent fractions, time, length and perimeter, and kinds of angle.","more":"Its lands: Adding in your head · Nines and twelves · Odds, evens and multiples · Equal fractions · Clocks, coins and measuring · Solids and angles.","where":"Level 3 · maths age 8","route":"#/journey/3","cta":"See the road"},"land-l3-addsub":{"id":"land-l3-addsub","kind":"land","level":3,"src":"land:l3-addsub","title":"Adding in your head — in The Mental Workshop","body":"4 stops on this stretch of the road: Column addition · Column subtraction · Round it, then fix it · Take too much, give it back.","art":"art/w-workshop.webp","more":"At its end, a 20-question test: 12 right passes, and 5 bonus questions count double.","where":"The Mental Workshop · Level 3","route":"#/world/workshop","cta":"Visit Workshop"},"land-l3-muldiv":{"id":"land-l3-muldiv","kind":"land","level":3,"src":"land:l3-muldiv","title":"Nines and twelves — in The Times Market","body":"4 stops on this stretch of the road: Times nine · Split the hard one · Split and multiply · Near ten: the cross.","art":"art/w-market.webp","more":"At its end, a 20-question test: 12 right passes, and 5 bonus questions count double.","where":"The Times Market · Level 3","route":"#/world/market","cta":"Visit Market"},"land-l3-factors":{"id":"land-l3-factors","kind":"land","level":3,"src":"land:l3-factors","title":"Odds, evens and multiples — in The Factor Forest","body":"3 stops on this stretch of the road: Odd and even rules · The next multiple · Tests for 2, 5 and 10.","art":"art/w-forest.webp","more":"At its end, a 20-question test: 12 right passes, and 5 bonus questions count double.","where":"The Factor Forest · Level 3","route":"#/world/forest","cta":"Visit Forest"},"land-l3-fractions":{"id":"land-l3-fractions","kind":"land","level":3,"src":"land:l3-fractions","title":"Equal fractions — in The Fraction Bakery","body":"4 stops on this stretch of the road: Halves, quarters and thirds · Same share, different pieces · Which slice is bigger? · Adding slices of the same size.","art":"art/w-bakery.webp","more":"At its end, a 20-question test: 12 right passes, and 5 bonus questions count double.","where":"The Fraction Bakery · Level 3","route":"#/world/bakery","cta":"Visit Bakery"},"land-l3-measure":{"id":"land-l3-measure","kind":"land","level":3,"src":"land:l3-measure","title":"Clocks, coins and measuring — in The Clock Tower","body":"5 stops on this stretch of the road: Giving change · How long is it? · Metres, grams and litres · Perimeter · Roman numerals.","art":"art/w-clocktower.webp","more":"At its end, a 20-question test: 12 right passes, and 5 bonus questions count double.","where":"The Clock Tower · Level 3","route":"#/world/clocktower","cta":"Visit Clock Tower"},"land-l3-shape":{"id":"land-l3-shape","kind":"land","level":3,"src":"land:l3-shape","title":"Solids and angles — in Shape City","body":"3 stops on this stretch of the road: Lines of symmetry · Faces, edges and corners · Kinds of angle.","art":"art/w-shapecity.webp","more":"At its end, a 20-question test: 12 right passes, and 5 bonus questions count double.","where":"Shape City · Level 3","route":"#/world/shapecity","cta":"Visit Shape City"},"trick-times-nine-idea":{"id":"trick-times-nine-idea","kind":"trick","src":"stop:times-nine#idea","title":"Times nine","body":"Ten lots, then take one lot away. Nine lots of 7 is ten lots of 7 with one lot missing.","more":"In algebra: n × 9 = n × 10 − n","cta":"Learn the trick","where":"The Times Market · Level 3","level":3,"route":"#/stop/times-nine|learn"},"story-times-nine-open":{"id":"story-times-nine-open","kind":"story","src":"story:times-nine#open","badge":{"id":"story","label":"A story"},"title":"Nine chairs a row","body":"The school hall has 7 rows of chairs, with 9 chairs in each row. — with Theo and Nova.","more":"The trick inside: Ten lots, then take one lot away.","art":"art/s-hall.webp","cta":"Read the story","where":"The Times Market · Level 3","level":3,"route":"#/stop/times-nine|story|0"},"hook-times-nine-hook":{"id":"hook-times-nine-hook","kind":"hook","src":"stop:times-nine#hook","title":"Can you? — Times nine","body":"7 × 9 — nine is one short of ten.","more":"The way in: Ten lots, then take one lot away.","cta":"Find out how","where":"The Times Market · Level 3","level":3,"route":"#/stop/times-nine|learn"},"worked-times-nine-worked0":{"id":"worked-times-nine-worked0","kind":"worked","src":"stop:times-nine#worked0","title":"Worked out — Times nine","body":"7 × 9: 7 × 10 → 70 · Take away one 7 → 63","more":"The method: Ten lots, then take one lot away.","cta":"Watch it step by step","where":"The Times Market · Level 3","level":3,"route":"#/stop/times-nine|learn|0"},"why-times-nine-why1":{"id":"why-times-nine-why1","kind":"why","src":"stop:times-nine#why1","title":"Why “Times nine” works","body":"Ten lots of 7 is 70. Take away one 7 and you have 63. (Look at the answers down the nine times table: the digits always add up to nine. That is the same reason, showing through.)","more":"The trick: Ten lots, then take one lot away.","cta":"See why","where":"The Times Market · Level 3","level":3,"route":"#/stop/times-nine|learn"},"algebra-times-nine-alg":{"id":"algebra-times-nine-alg","kind":"algebra","src":"stop:times-nine#alg","title":"The algebra behind “Times nine”","body":"n × 9 = n × 10 − n","more":"In words: Ten lots, then take one lot away.","cta":"See why","where":"The Times Market · Level 3","level":3,"route":"#/stop/times-nine|learn"},"moment-times-nine-beat3":{"id":"moment-times-nine-beat3","kind":"moment","src":"story:times-nine#beat3","badge":{"id":"story","label":"A story"},"title":"Nine chairs a row — on the notepad","body":"Theo: Seven rows, one short each — so 7 chairs fewer. 70 − 7 = 63","more":"The trick in the story: Ten lots, then take one lot away.","cta":"Read the story","where":"The Times Market · Level 3","level":3,"route":"#/stop/times-nine|story|3"},"moral-times-nine-beat5":{"id":"moral-times-nine-beat5","kind":"moral","src":"story:times-nine#beat5","badge":{"id":"story","label":"A story"},"title":"Theo, in “Nine chairs a row”","body":"And 6 and 3 make 9. Answers in the nine times table always add up to nine — that is my check.","more":"The trick in the story: Ten lots, then take one lot away.","cta":"Read the story","where":"The Times Market · Level 3","level":3,"route":"#/stop/times-nine|story|5"},"try-times-nine-L3":{"id":"try-times-nine-L3","kind":"try","level":3,"src":"try:times-nine@3/1#0","title":"Times nine — your turn","where":"The Times Market · Level 3","route":"#/stop/times-nine|drill","cta":"Practise this stop","play":{"q":"3 × 9 = ?","opts":["27","30","28"],"after":"Ten lots, then take one lot away."}},"trick-times-twelve-idea":{"id":"trick-times-twelve-idea","kind":"trick","src":"stop:times-twelve#idea","title":"Split the hard one","body":"Twelve is ten and two. Do each, then add. Seven lots of 12 is seven lots of 10 and seven lots of 2, side by side.","more":"In algebra: n × 12 = n × 10 + n × 2","cta":"Learn the trick","where":"The Times Market · Level 3","level":3,"route":"#/stop/times-twelve|learn"},"story-times-twelve-open":{"id":"story-times-twelve-open","kind":"story","src":"story:times-twelve#open","badge":{"id":"story","label":"A story"},"title":"Boxes of a dozen","body":"Mangoes come in boxes of 12. The stall has 7 boxes. — with Rafi and Ines.","more":"The trick inside: Twelve is ten and two. Do each, then add.","art":"art/s-market.webp","cta":"Read the story","where":"The Times Market · Level 3","level":3,"route":"#/stop/times-twelve|story|0"},"worked-times-twelve-worked0":{"id":"worked-times-twelve-worked0","kind":"worked","src":"stop:times-twelve#worked0","title":"Worked out — Split the hard one","body":"7 × 12: 7 × 10 → 70 · 7 × 2 → 14 · Add them → 84","more":"The method: Twelve is ten and two. Do each, then add.","cta":"Watch it step by step","where":"The Times Market · Level 3","level":3,"route":"#/stop/times-twelve|learn|0"},"algebra-times-twelve-alg":{"id":"algebra-times-twelve-alg","kind":"algebra","src":"stop:times-twelve#alg","title":"The algebra behind “Split the hard one”","body":"n × 12 = n × 10 + n × 2","more":"In words: Twelve is ten and two. Do each, then add.","cta":"See why","where":"The Times Market · Level 3","level":3,"route":"#/stop/times-twelve|learn"},"moral-times-twelve-beat6":{"id":"moral-times-twelve-beat6","kind":"moral","src":"story:times-twelve#beat6","badge":{"id":"story","label":"A story"},"title":"Ines, in “Boxes of a dozen”","body":"Eighty-four mangoes. Two easy sums instead of one hard one.","more":"The trick in the story: Twelve is ten and two. Do each, then add.","cta":"Read the story","where":"The Times Market · Level 3","level":3,"route":"#/stop/times-twelve|story|6"},"try-times-twelve-L3":{"id":"try-times-twelve-L3","kind":"try","level":3,"src":"try:times-twelve@3/1#0","title":"Split the hard one — your turn","where":"The Times Market · Level 3","route":"#/stop/times-twelve|drill","cta":"Practise this stop","play":{"q":"5 × 12 = ?","opts":["60","50","10"],"after":"Twelve is ten and two. Do each, then add."}},"hook-column-add-hook":{"id":"hook-column-add-hook","kind":"hook","src":"stop:column-add#hook","title":"Can you? — Column addition","body":"368 + 457 — too big for your fingers, and your head.","more":"The way in: Line the numbers up by place. Add each column from the right; when a column makes ten or more, carry the ten to the next column.","cta":"Find out how","where":"The Number Library · Level 3","level":3,"route":"#/stop/column-add|learn"},"worked-column-add-worked0":{"id":"worked-column-add-worked0","kind":"worked","src":"stop:column-add#worked0","title":"Worked out — Column addition: One carry","body":"246 + 137: Ones: 6 + 7 → 13 · Tens: 4 + 3 + 1 carried → 8 · Hundreds: 2 + 1 → 3 · Keep the last digit of each column, carry the tens — read the answer → 383","more":"What is special here: Only the ones make ten or more. Their ten goes to the top of the tens column and is added in with the tens.","cta":"Watch it step by step","where":"The Number Library · Level 3","level":3,"route":"#/stop/column-add|learn|0"},"worked-column-add-worked1":{"id":"worked-column-add-worked1","kind":"worked","src":"stop:column-add#worked1","title":"Worked out — Column addition: Carry after carry","body":"368 + 457: Ones: 8 + 7 → 15 · Tens: 6 + 5 + 1 carried → 12 · Hundreds: 3 + 4 + 1 carried → 8 · Keep the last digit of each column, carry the tens — read the answer → 825","more":"What is special here: The carried one can make the next column reach ten too — then that column carries as well. Always add the carry in.","cta":"Watch it step by step","where":"The Number Library · Level 3","level":3,"route":"#/stop/column-add|learn|1"},"worked-column-add-worked2":{"id":"worked-column-add-worked2","kind":"worked","src":"stop:column-add#worked2","title":"Worked out — Column addition: A carry makes a new place","body":"68 + 57: Ones: 8 + 7 → 15 · Tens: 6 + 5 + 1 carried → 12 · Keep the last digit of each column, carry the tens — read the answer → 125","more":"What is special here: The last column carries too, and there is nothing to its left. The carried one starts a new place of its own at the front.","cta":"Watch it step by step","where":"The Number Library · Level 3","level":3,"route":"#/stop/column-add|learn|2"},"why-column-add-why2":{"id":"why-column-add-why2","kind":"why","src":"stop:column-add#why2","title":"Why “Column addition” works","body":"We start on the right because that is where carries come from. Each column might send one to its left neighbour, never to its right, so going right to left means nothing ever needs fixing afterwards.","more":"The trick: Line the numbers up by place. Add each column from the right; when a column makes ten or more, carry the ten to the next column.","cta":"See why","where":"The Number Library · Level 3","level":3,"route":"#/stop/column-add|learn"},"moment-column-add-beat3":{"id":"moment-column-add-beat3","kind":"moment","src":"story:column-add#beat3","badge":{"id":"story","label":"A story"},"title":"The book sale — on the notepad","body":"Rafi: Keep the 5, and carry the ten over to the tens. Tens: 6 and 5, and the 1 carried. 6 + 5 + 1 = 12","more":"The trick in the story: Line the numbers up by place. Add each column from the right; when a column makes ten or more, carry the ten to the next column.","cta":"Read the story","where":"The Number Library · Level 3","level":3,"route":"#/stop/column-add|story|3"},"try-column-add-L3":{"id":"try-column-add-L3","kind":"try","level":3,"src":"try:column-add@3/2#0","title":"Column addition — your turn","where":"The Number Library · Level 3","route":"#/stop/column-add|drill","cta":"Practise this stop","play":{"q":"737 + 433 = ?","opts":["1170","10","7"],"after":"Line the numbers up by place. Add each column from the right; when a column makes ten or more, carry the ten to the next column."}},"hook-column-sub-hook":{"id":"hook-column-sub-hook","kind":"hook","src":"stop:column-sub#hook","title":"Can you? — Column subtraction","body":"532 − 178 — the top digit is smaller. Now what?","more":"The way in: Line up by place and subtract from the right. When the top digit is too small, exchange one from the next column: it arrives as ten.","cta":"Find out how","where":"The Number Library · Level 3","level":3,"route":"#/stop/column-sub|learn"},"worked-column-sub-worked0":{"id":"worked-column-sub-worked0","kind":"worked","src":"stop:column-sub#worked0","title":"Worked out — Column subtraction: One exchange","body":"72 − 38: Ones: 2 is less than 8 — exchange 1 from the left. 12 − 8 → 4 · Tens: 6 (after lending 1) − 3 → 3 · Read the answer → 34","more":"What is special here: Only the ones are too small. One ten from next door becomes ten ones, and the tens column has one fewer to give.","cta":"Watch it step by step","where":"The Number Library · Level 3","level":3,"route":"#/stop/column-sub|learn|0"},"worked-column-sub-worked1":{"id":"worked-column-sub-worked1","kind":"worked","src":"stop:column-sub#worked1","title":"Worked out — Column subtraction: Exchange after exchange","body":"532 − 178: Ones: 2 is less than 8 — exchange 1 from the left. 12 − 8 → 4 · Tens: 2 is less than 7 — exchange 1 from the left. 12 − 7 → 5 · Hundreds: 4 (after lending 1) − 1 → 3 · Read the answer → 354","more":"What is special here: After lending, the tens are too small as well — so they exchange from the hundreds. Remember each column has one fewer after it lends.","cta":"Watch it step by step","where":"The Number Library · Level 3","level":3,"route":"#/stop/column-sub|learn|1"},"worked-column-sub-worked2":{"id":"worked-column-sub-worked2","kind":"worked","src":"stop:column-sub#worked2","title":"Worked out — Column subtraction: Across a zero","body":"4003 − 1257: Ones: 3 is less than 7 — exchange 1 from the left. 13 − 7 → 6 · Tens: this 0 had to exchange from its left too, so it is now 9. 9 − 5 → 4 · Hundreds: this 0 had to exchange from its left too, so it is now 9. 9 − 2 → 7 · Thousands: 3 (after lending 1) − 1 → 2 · Read the answer → 2746","more":"What is special here: The next column is a 0 with nothing to lend, so it exchanges from ITS neighbour first. That is why the 0s turn into 9s.","cta":"Watch it step by step","where":"The Number Library · Level 3","level":3,"route":"#/stop/column-sub|learn|2"},"why-column-sub-why2":{"id":"why-column-sub-why2","kind":"why","src":"stop:column-sub#why2","title":"Why “Column subtraction” works","body":"When the next column is a 0 it has nothing to lend, so it exchanges from its own neighbour first: 1 hundred becomes 10 tens, and then one of those tens goes on to the ones. That is why 0s in the top number turn into 9s.","more":"The trick: Line up by place and subtract from the right. When the top digit is too small, exchange one from the next column: it arrives as ten.","cta":"See why","where":"The Number Library · Level 3","level":3,"route":"#/stop/column-sub|learn"},"moment-column-sub-beat3":{"id":"moment-column-sub-beat3","kind":"moment","src":"story:column-sub#beat3","badge":{"id":"story","label":"A story"},"title":"Books still out — on the notepad","body":"Suki: The tens gave one away, so 3 is now 2. 2 take 7 — exchange again. 12 − 7 = 5","more":"The trick in the story: Line up by place and subtract from the right. When the top digit is too small, exchange one from the next column: it arrives as ten.","cta":"Read the story","where":"The Number Library · Level 3","level":3,"route":"#/stop/column-sub|story|3"},"try-column-sub-L3":{"id":"try-column-sub-L3","kind":"try","level":3,"src":"try:column-sub@3/2#0","title":"Column subtraction — your turn","where":"The Number Library · Level 3","route":"#/stop/column-sub|drill","cta":"Practise this stop","play":{"q":"760 − 315 = ?","opts":["445","5","4"],"after":"Line up by place and subtract from the right. When the top digit is too small, exchange one from the next column: it arrives as ten."}},"trick-roman-numerals-idea":{"id":"trick-roman-numerals-idea","kind":"trick","src":"stop:roman-numerals#idea","title":"Roman numerals","body":"Read left to right and add — except when a smaller letter comes just before a bigger one, which means take it away. Roman numerals use seven letters: I is 1, V is 5, X is 10, L is 50, C is 100, D is 500 and M is 1000. There is no zero and no place value: a letter is worth the same wherever it stands. So you build a number by adding letters up — XXVI is 10 + 10 + 5 + 1 = 26.","more":"In algebra: value = Σ letters, with a letter subtracted when it stands before a larger one","cta":"Learn the trick","where":"The Number Library · Level 3","level":3,"route":"#/stop/roman-numerals|learn"},"story-roman-numerals-open":{"id":"story-roman-numerals-open","kind":"story","src":"story:roman-numerals#open","badge":{"id":"story","label":"A story"},"title":"The old clock","body":"On a shelf in Mira’s room is an old clock. Rafi spots letters on its face instead of numbers. — with Mira and Rafi.","more":"The trick inside: Read left to right and add — except when a smaller letter comes just before a bigger one, which means take it away.","art":"art/s-room.webp","cta":"Read the story","where":"The Number Library · Level 3","level":3,"route":"#/stop/roman-numerals|story|0"},"hook-roman-numerals-hook":{"id":"hook-roman-numerals-hook","kind":"hook","src":"stop:roman-numerals#hook","title":"Can you? — Roman numerals","body":"MCMXLIV — a number written with letters. Which number?","more":"The way in: Read left to right and add — except when a smaller letter comes just before a bigger one, which means take it away.","cta":"Find out how","where":"The Number Library · Level 3","level":3,"route":"#/stop/roman-numerals|learn"},"idea-roman-numerals-case0":{"id":"idea-roman-numerals-case0","kind":"idea","src":"stop:roman-numerals#case0","title":"Roman numerals: Read one that only adds","body":"Every letter is the same size or smaller than the one before it, so just add them all up.","more":"The method: Read left to right and add — except when a smaller letter comes just before a bigger one, which means take it away.","cta":"See it worked","where":"The Number Library · Level 3","level":3,"route":"#/stop/roman-numerals|learn|0"},"worked-roman-numerals-worked0":{"id":"worked-roman-numerals-worked0","kind":"worked","src":"stop:roman-numerals#worked0","title":"Worked out — Roman numerals: Read one that only adds","body":"What number is XXVI?: Split by place: XX is → 20 · Split by place: VI is → 6 · Add the parts → 26","more":"What is special here: Every letter is the same size or smaller than the one before it, so just add them all up.","cta":"Watch it step by step","where":"The Number Library · Level 3","level":3,"route":"#/stop/roman-numerals|learn|0"},"idea-roman-numerals-case1":{"id":"idea-roman-numerals-case1","kind":"idea","src":"stop:roman-numerals#case1","title":"Roman numerals: Read one that takes away","body":"A smaller letter just before a bigger one is taken away: CM is 900, XL is 40, IV is 4. Split it by place and add the parts.","more":"The method: Read left to right and add — except when a smaller letter comes just before a bigger one, which means take it away.","cta":"See it worked","where":"The Number Library · Level 3","level":3,"route":"#/stop/roman-numerals|learn|1"},"worked-roman-numerals-worked1":{"id":"worked-roman-numerals-worked1","kind":"worked","src":"stop:roman-numerals#worked1","title":"Worked out — Roman numerals: Read one that takes away","body":"What number is MCMXLIV?: Split by place: M is → 1000 · Split by place: CM is → 900 · Split by place: XL is → 40 · Split by place: IV is → 4 · Add the parts → 1944","more":"What is special here: A smaller letter just before a bigger one is taken away: CM is 900, XL is 40, IV is 4. Split it by place and add the parts.","cta":"Watch it step by step","where":"The Number Library · Level 3","level":3,"route":"#/stop/roman-numerals|learn|1"},"idea-roman-numerals-case2":{"id":"idea-roman-numerals-case2","kind":"idea","src":"stop:roman-numerals#case2","title":"Roman numerals: Write one that only adds","body":"Split the number by place and write each part, biggest first. No part here needs a take-away pair.","more":"The method: Read left to right and add — except when a smaller letter comes just before a bigger one, which means take it away.","cta":"See it worked","where":"The Number Library · Level 3","level":3,"route":"#/stop/roman-numerals|learn|2"},"worked-roman-numerals-worked2":{"id":"worked-roman-numerals-worked2","kind":"worked","src":"stop:roman-numerals#worked2","title":"Worked out — Roman numerals: Write one that only adds","body":"Which is 27 in Roman numerals?: Split 27 by place — the biggest part → 20 · The next part → 7 · Write each part as a numeral, biggest first → XXVII","more":"What is special here: Split the number by place and write each part, biggest first. No part here needs a take-away pair.","cta":"Watch it step by step","where":"The Number Library · Level 3","level":3,"route":"#/stop/roman-numerals|learn|2"},"idea-roman-numerals-case3":{"id":"idea-roman-numerals-case3","kind":"idea","src":"stop:roman-numerals#case3","title":"Roman numerals: Write one that takes away","body":"A 4 or a 9 in any place is written as a take-away pair — 40 is XL and 9 is IX — never four of the same letter.","more":"The method: Read left to right and add — except when a smaller letter comes just before a bigger one, which means take it away.","cta":"See it worked","where":"The Number Library · Level 3","level":3,"route":"#/stop/roman-numerals|learn|3"},"worked-roman-numerals-worked3":{"id":"worked-roman-numerals-worked3","kind":"worked","src":"stop:roman-numerals#worked3","title":"Worked out — Roman numerals: Write one that takes away","body":"Which is 49 in Roman numerals?: Split 49 by place — the biggest part → 40 · The next part → 9 · Write each part as a numeral, biggest first → XLIX","more":"What is special here: A 4 or a 9 in any place is written as a take-away pair — 40 is XL and 9 is IX — never four of the same letter.","cta":"Watch it step by step","where":"The Number Library · Level 3","level":3,"route":"#/stop/roman-numerals|learn|3"},"why-roman-numerals-why1":{"id":"why-roman-numerals-why1","kind":"why","src":"stop:roman-numerals#why1","title":"Why “Roman numerals” works","body":"To keep them short, the way they are usually written today never repeats a letter more than three times. Four is not IIII but IV: the I stands before the V, so it is taken away — one less than five. Only I, X and C are used like this, and only in front of the next two letters up: IV, IX, XL, XC, CD, CM.","more":"The trick: Read left to right and add — except when a smaller letter comes just before a bigger one, which means take it away.","cta":"See why","where":"The Number Library · Level 3","level":3,"route":"#/stop/roman-numerals|learn"},"why-roman-numerals-why2":{"id":"why-roman-numerals-why2","kind":"why","src":"stop:roman-numerals#why2","title":"Why “Roman numerals” works","body":"The easiest way to read a long one is to split it by our places. MCMXLIV is M (1000), CM (900), XL (40) and IV (4). Each part is one digit of our number, which is why the two systems can be translated place by place.","more":"The trick: Read left to right and add — except when a smaller letter comes just before a bigger one, which means take it away.","cta":"See why","where":"The Number Library · Level 3","level":3,"route":"#/stop/roman-numerals|learn"},"algebra-roman-numerals-alg":{"id":"algebra-roman-numerals-alg","kind":"algebra","src":"stop:roman-numerals#alg","title":"The algebra behind “Roman numerals”","body":"value = Σ letters, with a letter subtracted when it stands before a larger one","more":"In words: Read left to right and add — except when a smaller letter comes just before a bigger one, which means take it away.","cta":"See why","where":"The Number Library · Level 3","level":3,"route":"#/stop/roman-numerals|learn"},"moment-roman-numerals-beat3":{"id":"moment-roman-numerals-beat3","kind":"moment","src":"story:roman-numerals#beat3","badge":{"id":"story","label":"A story"},"title":"The old clock — on the notepad","body":"Rafi: And XII at the top is 10 and 1 and 1. 10 + 1 + 1 = 12","more":"The trick in the story: Read left to right and add — except when a smaller letter comes just before a bigger one, which means take it away.","cta":"Read the story","where":"The Number Library · Level 3","level":3,"route":"#/stop/roman-numerals|story|3"},"moral-roman-numerals-beat5":{"id":"moral-roman-numerals-beat5","kind":"moral","src":"story:roman-numerals#beat5","badge":{"id":"story","label":"A story"},"title":"Rafi, in “The old clock”","body":"XL is ten less than fifty, and IV is one less than five.","more":"The trick in the story: Read left to right and add — except when a smaller letter comes just before a bigger one, which means take it away.","cta":"Read the story","where":"The Number Library · Level 3","level":3,"route":"#/stop/roman-numerals|story|5"},"try-roman-numerals-L3":{"id":"try-roman-numerals-L3","kind":"try","level":3,"src":"try:roman-numerals@3/1#0","title":"Roman numerals — your turn","where":"The Number Library · Level 3","route":"#/stop/roman-numerals|drill","cta":"Practise this stop","play":{"q":"Which is 10 in Roman numerals?","opts":["X","IX","XI"],"after":"Read left to right and add — except when a smaller letter comes just before a bigger one, which means take it away."}},"hook-giving-change-hook":{"id":"hook-giving-change-hook","kind":"hook","src":"stop:giving-change#hook","title":"Can you? — Giving change","body":"Something costs 37 coins and you pay with 50. How much comes back?","more":"The way in: Count UP from the price to what you paid — to the next ten first, then on. The jumps are the change.","cta":"Find out how","where":"The Clock Tower · Level 3","level":3,"route":"#/stop/giving-change|learn"},"idea-giving-change-case1":{"id":"idea-giving-change-case1","kind":"idea","src":"stop:giving-change#case1","title":"Giving change: Buying several","body":"Find the total first — the price times how many — and only then count up from the total to what you paid.","more":"The method: Count UP from the price to what you paid — to the next ten first, then on. The jumps are the change.","cta":"See it worked","where":"The Clock Tower · Level 3","level":3,"route":"#/stop/giving-change|learn|1"},"why-giving-change-why2":{"id":"why-giving-change-why2","kind":"why","src":"stop:giving-change#why2","title":"Why “Giving change” works","body":"If you buy several of the same thing, find the total first — price times how many — then count up from the total.","more":"The trick: Count UP from the price to what you paid — to the next ten first, then on. The jumps are the change.","cta":"See why","where":"The Clock Tower · Level 3","level":3,"route":"#/stop/giving-change|learn"},"moral-giving-change-beat5":{"id":"moral-giving-change-beat5","kind":"moral","src":"story:giving-change#beat5","badge":{"id":"story","label":"A story"},"title":"Dax, in “The comic stall”","body":"Thirteen coins change. No borrowing at all.","more":"The trick in the story: Count UP from the price to what you paid — to the next ten first, then on. The jumps are the change.","cta":"Read the story","where":"The Clock Tower · Level 3","level":3,"route":"#/stop/giving-change|story|5"},"try-giving-change-L3":{"id":"try-giving-change-L3","kind":"try","level":3,"src":"try:giving-change@3/2#0","title":"Giving change — your turn","where":"The Clock Tower · Level 3","route":"#/stop/giving-change|drill","cta":"Practise this stop","play":{"q":"A apple costs 30 coins. You pay with 50 coins. How many coins do you get back?","opts":["20","21","19"],"after":"Count UP from the price to what you paid — to the next ten first, then on. The jumps are the change."}},"trick-how-long-idea":{"id":"trick-how-long-idea","kind":"trick","src":"stop:how-long#idea","title":"How long is it?","body":"Jump to the next o'clock, then whole hours, then the minutes left over — and add the jumps. Time does not work in tens. An hour is 60 minutes, so 4:15 − 2:40 written as 415 − 240 gives 175, which is wrong. The clock rolls over at 60, not at 100. (When both times are inside the same hour, nothing rolls over, and you can simply take the minutes away.)","more":"In algebra: time = (60 − start minutes) + 60 × whole hours + end minutes","cta":"Learn the trick","where":"The Clock Tower · Level 3","level":3,"route":"#/stop/how-long|learn"},"story-how-long-open":{"id":"story-how-long-open","kind":"story","src":"story:how-long#open","badge":{"id":"story","label":"A story"},"title":"The film on the train","body":"On a long train ride, Pip starts a film at 2:40. It ends at 4:15. — with Theo and Pip.","more":"The trick inside: Jump to the next o'clock, then whole hours, then the minutes left over — and add the jumps.","art":"art/s-train.webp","cta":"Read the story","where":"The Clock Tower · Level 3","level":3,"route":"#/stop/how-long|story|0"},"hook-how-long-hook":{"id":"hook-how-long-hook","kind":"hook","src":"stop:how-long#hook","title":"Can you? — How long is it?","body":"The film starts at 2:40 and ends at 4:15. How many minutes long is it?","more":"The way in: Jump to the next o'clock, then whole hours, then the minutes left over — and add the jumps.","cta":"Find out how","where":"The Clock Tower · Level 3","level":3,"route":"#/stop/how-long|learn"},"idea-how-long-case0":{"id":"idea-how-long-case0","kind":"idea","src":"stop:how-long#case0","title":"How long is it?: Inside one hour","body":"Both times are in the same hour, so no o'clock is crossed: take the start minutes from the end minutes.","more":"The method: Jump to the next o'clock, then whole hours, then the minutes left over — and add the jumps.","cta":"See it worked","where":"The Clock Tower · Level 3","level":3,"route":"#/stop/how-long|learn|0"},"worked-how-long-worked0":{"id":"worked-how-long-worked0","kind":"worked","src":"stop:how-long#worked0","title":"Worked out — How long is it?: Inside one hour","body":"How many minutes is it from 3:10 to 3:45?: Minutes past the hour at the start → 10 · Minutes past the hour at the end → 45 · 45 − 10 → 35","more":"What is special here: Both times are in the same hour, so no o'clock is crossed: take the start minutes from the end minutes.","cta":"Watch it step by step","where":"The Clock Tower · Level 3","level":3,"route":"#/stop/how-long|learn|0"},"idea-how-long-case1":{"id":"idea-how-long-case1","kind":"idea","src":"stop:how-long#case1","title":"How long is it?: Across one o'clock","body":"The end has fewer minutes than the start, so you cannot just take away. Jump to the o'clock, then on to the end.","more":"The method: Jump to the next o'clock, then whole hours, then the minutes left over — and add the jumps.","cta":"See it worked","where":"The Clock Tower · Level 3","level":3,"route":"#/stop/how-long|learn|1"},"worked-how-long-worked1":{"id":"worked-how-long-worked1","kind":"worked","src":"stop:how-long#worked1","title":"Worked out — How long is it?: Across one o'clock","body":"How many minutes is it from 2:40 to 3:15?: 2:40 up to 3:00 → 20 · 3:00 up to 3:15 → 15 · Add the jumps → 35","more":"What is special here: The end has fewer minutes than the start, so you cannot just take away. Jump to the o'clock, then on to the end.","cta":"Watch it step by step","where":"The Clock Tower · Level 3","level":3,"route":"#/stop/how-long|learn|1"},"idea-how-long-case2":{"id":"idea-how-long-case2","kind":"idea","src":"stop:how-long#case2","title":"How long is it?: Across several hours","body":"Jump to the next o'clock, then count whole hours as 60 minutes each, then the minutes left over.","more":"The method: Jump to the next o'clock, then whole hours, then the minutes left over — and add the jumps.","cta":"See it worked","where":"The Clock Tower · Level 3","level":3,"route":"#/stop/how-long|learn|2"},"worked-how-long-worked2":{"id":"worked-how-long-worked2","kind":"worked","src":"stop:how-long#worked2","title":"Worked out — How long is it?: Across several hours","body":"How many minutes is it from 2:40 to 4:15?: 2:40 up to 3:00 → 20 · 3:00 up to 4:00 — one hour in minutes → 60 · 4:00 up to 4:15 → 15 · Add the jumps → 95","more":"What is special here: Jump to the next o'clock, then count whole hours as 60 minutes each, then the minutes left over.","cta":"Watch it step by step","where":"The Clock Tower · Level 3","level":3,"route":"#/stop/how-long|learn|2"},"why-how-long-why1":{"id":"why-how-long-why1","kind":"why","src":"stop:how-long#why1","title":"Why “How long is it?” works","body":"O'clock is to time what a round ten is to numbers: the easy place to jump to. From 2:40 to 3:00 is 20 minutes. From 3:00 to 4:00 is a whole hour, 60 minutes. From 4:00 to 4:15 is 15 minutes.","more":"The trick: Jump to the next o'clock, then whole hours, then the minutes left over — and add the jumps.","cta":"See why","where":"The Clock Tower · Level 3","level":3,"route":"#/stop/how-long|learn"},"why-how-long-why2":{"id":"why-how-long-why2","kind":"why","src":"stop:how-long#why2","title":"Why “How long is it?” works","body":"The film fills every one of those jumps and nothing else, so its length is the jumps added up: 20 + 60 + 15 = 95 minutes.","more":"The trick: Jump to the next o'clock, then whole hours, then the minutes left over — and add the jumps.","cta":"See why","where":"The Clock Tower · Level 3","level":3,"route":"#/stop/how-long|learn"},"algebra-how-long-alg":{"id":"algebra-how-long-alg","kind":"algebra","src":"stop:how-long#alg","title":"The algebra behind “How long is it?”","body":"time = (60 − start minutes) + 60 × whole hours + end minutes","more":"In words: Jump to the next o'clock, then whole hours, then the minutes left over — and add the jumps.","cta":"See why","where":"The Clock Tower · Level 3","level":3,"route":"#/stop/how-long|learn"},"moment-how-long-beat3":{"id":"moment-how-long-beat3","kind":"moment","src":"story:how-long#beat3","badge":{"id":"story","label":"A story"},"title":"The film on the train — on the notepad","body":"Pip: Then 3:00 to 4:00 is a whole hour. 1 × 60 = 60","more":"The trick in the story: Jump to the next o'clock, then whole hours, then the minutes left over — and add the jumps.","cta":"Read the story","where":"The Clock Tower · Level 3","level":3,"route":"#/stop/how-long|story|3"},"moral-how-long-beat5":{"id":"moral-how-long-beat5","kind":"moral","src":"story:how-long#beat5","badge":{"id":"story","label":"A story"},"title":"Pip, in “The film on the train”","body":"Add the jumps: 95 minutes. Much shorter than I said!","more":"The trick in the story: Jump to the next o'clock, then whole hours, then the minutes left over — and add the jumps.","cta":"Read the story","where":"The Clock Tower · Level 3","level":3,"route":"#/stop/how-long|story|5"},"try-how-long-L3":{"id":"try-how-long-L3","kind":"try","level":3,"src":"try:how-long@3/1#0","title":"How long is it? — your turn","where":"The Clock Tower · Level 3","route":"#/stop/how-long|drill","cta":"Practise this stop","play":{"q":"How many minutes is it from 5:05 to 5:25?","opts":["20","5","25"],"after":"Jump to the next o'clock, then whole hours, then the minutes left over — and add the jumps."}},"trick-metric-units-idea":{"id":"trick-metric-units-idea","kind":"trick","src":"stop:metric-units#idea","title":"Metres, grams and litres","body":"Know how many small units make one big one (10, 100 or 1000), then multiply to go down or divide to go up. The metric units are built from their names. Kilo- means a thousand: a kilometre is 1000 metres, a kilogram 1000 grams. Centi- means a hundredth: 100 centimetres make a metre. Milli- means a thousandth: 1000 millilitres make a litre, and 10 millimetres make a centimetre.","more":"In algebra: big → small: × f · small → big: ÷ f (f = 10, 100 or 1000)","cta":"Learn the trick","where":"The Clock Tower · Level 3","level":3,"route":"#/stop/metric-units|learn"},"story-metric-units-open":{"id":"story-metric-units-open","kind":"story","src":"story:metric-units#open","badge":{"id":"story","label":"A story"},"title":"The ribbon and the flour","body":"In the kitchen, Nova measures ribbon for a cake: 3 m 45 cm. The recipe wants it in centimetres. — with Rafi and Nova.","more":"The trick inside: Know how many small units make one big one (10, 100 or 1000), then multiply to go down or divide to go up.","art":"art/s-kitchen.webp","cta":"Read the story","where":"The Clock Tower · Level 3","level":3,"route":"#/stop/metric-units|story|0"},"hook-metric-units-hook":{"id":"hook-metric-units-hook","kind":"hook","src":"stop:metric-units#hook","title":"Can you? — Metres, grams and litres","body":"3 m 45 cm of ribbon — how many centimetres is that?","more":"The way in: Know how many small units make one big one (10, 100 or 1000), then multiply to go down or divide to go up.","cta":"Find out how","where":"The Clock Tower · Level 3","level":3,"route":"#/stop/metric-units|learn"},"idea-metric-units-case0":{"id":"idea-metric-units-case0","kind":"idea","src":"stop:metric-units#case0","title":"Metres, grams and litres: Big unit to small","body":"Every big unit breaks into 10, 100 or 1000 small ones, so going down you multiply.","more":"The method: Know how many small units make one big one (10, 100 or 1000), then multiply to go down or divide to go up.","cta":"See it worked","where":"The Clock Tower · Level 3","level":3,"route":"#/stop/metric-units|learn|0"},"worked-metric-units-worked0":{"id":"worked-metric-units-worked0","kind":"worked","src":"stop:metric-units#worked0","title":"Worked out — Metres, grams and litres: Big unit to small","body":"How many g is 4 kg?: How many g make 1 kg? → 1000 · 4 × 1000 → 4000","more":"What is special here: Every big unit breaks into 10, 100 or 1000 small ones, so going down you multiply.","cta":"Watch it step by step","where":"The Clock Tower · Level 3","level":3,"route":"#/stop/metric-units|learn|0"},"idea-metric-units-case1":{"id":"idea-metric-units-case1","kind":"idea","src":"stop:metric-units#case1","title":"Metres, grams and litres: Two units at once","body":"Change the big units into small ones first, then add on the small ones that were already there.","more":"The method: Know how many small units make one big one (10, 100 or 1000), then multiply to go down or divide to go up.","cta":"See it worked","where":"The Clock Tower · Level 3","level":3,"route":"#/stop/metric-units|learn|1"},"worked-metric-units-worked1":{"id":"worked-metric-units-worked1","kind":"worked","src":"stop:metric-units#worked1","title":"Worked out — Metres, grams and litres: Two units at once","body":"How many cm is 3 m 45 cm?: How many cm make 1 m? → 100 · 3 × 100 → 300 · Add the 45 cm → 345","more":"What is special here: Change the big units into small ones first, then add on the small ones that were already there.","cta":"Watch it step by step","where":"The Clock Tower · Level 3","level":3,"route":"#/stop/metric-units|learn|1"},"idea-metric-units-case2":{"id":"idea-metric-units-case2","kind":"idea","src":"stop:metric-units#case2","title":"Metres, grams and litres: A decimal, big to small","body":"2.5 litres is two and a half lots of 1000 ml, so it still multiplies — and × 1000 slides the digits three places.","more":"The method: Know how many small units make one big one (10, 100 or 1000), then multiply to go down or divide to go up.","cta":"See it worked","where":"The Clock Tower · Level 3","level":3,"route":"#/stop/metric-units|learn|2"},"worked-metric-units-worked2":{"id":"worked-metric-units-worked2","kind":"worked","src":"stop:metric-units#worked2","title":"Worked out — Metres, grams and litres: A decimal, big to small","body":"How many ml is 2.5 l?: How many ml make 1 l? → 1000 · 2.5 × 1000 → 2500","more":"What is special here: 2.5 litres is two and a half lots of 1000 ml, so it still multiplies — and × 1000 slides the digits three places.","cta":"Watch it step by step","where":"The Clock Tower · Level 3","level":3,"route":"#/stop/metric-units|learn|2"},"idea-metric-units-case3":{"id":"idea-metric-units-case3","kind":"idea","src":"stop:metric-units#case3","title":"Metres, grams and litres: Small unit to big","body":"Going up you are grouping small units into big ones, so you divide — and the answer can be a decimal.","more":"The method: Know how many small units make one big one (10, 100 or 1000), then multiply to go down or divide to go up.","cta":"See it worked","where":"The Clock Tower · Level 3","level":3,"route":"#/stop/metric-units|learn|3"},"worked-metric-units-worked3":{"id":"worked-metric-units-worked3","kind":"worked","src":"stop:metric-units#worked3","title":"Worked out — Metres, grams and litres: Small unit to big","body":"How many m is 450 cm?: How many cm make 1 m? → 100 · 450 ÷ 100 → 4.5","more":"What is special here: Going up you are grouping small units into big ones, so you divide — and the answer can be a decimal.","cta":"Watch it step by step","where":"The Clock Tower · Level 3","level":3,"route":"#/stop/metric-units|learn|3"},"why-metric-units-why1":{"id":"why-metric-units-why1","kind":"why","src":"stop:metric-units#why1","title":"Why “Metres, grams and litres” works","body":"Going from a big unit to a small one, every big one breaks into that many small ones, so you multiply: 3 m is three lots of 100 cm, 300 cm. Going the other way, you are sharing small ones into groups, so you divide: 450 cm is 450 ÷ 100 = 4.5 m.","more":"The trick: Know how many small units make one big one (10, 100 or 1000), then multiply to go down or divide to go up.","cta":"See why","where":"The Clock Tower · Level 3","level":3,"route":"#/stop/metric-units|learn"},"why-metric-units-why2":{"id":"why-metric-units-why2","kind":"why","src":"stop:metric-units#why2","title":"Why “Metres, grams and litres” works","body":"Because every step is a 10, 100 or 1000, multiplying and dividing only slides the digits along — which is exactly why the whole world's scientists use these units.","more":"The trick: Know how many small units make one big one (10, 100 or 1000), then multiply to go down or divide to go up.","cta":"See why","where":"The Clock Tower · Level 3","level":3,"route":"#/stop/metric-units|learn"},"algebra-metric-units-alg":{"id":"algebra-metric-units-alg","kind":"algebra","src":"stop:metric-units#alg","title":"The algebra behind “Metres, grams and litres”","body":"big → small: × f · small → big: ÷ f (f = 10, 100 or 1000)","more":"In words: Know how many small units make one big one (10, 100 or 1000), then multiply to go down or divide to go up.","cta":"See why","where":"The Clock Tower · Level 3","level":3,"route":"#/stop/metric-units|learn"},"moment-metric-units-beat3":{"id":"moment-metric-units-beat3","kind":"moment","src":"story:metric-units#beat3","badge":{"id":"story","label":"A story"},"title":"The ribbon and the flour — on the notepad","body":"Rafi: Then add the 45 cm on the end. 300 + 45 = 345","more":"The trick in the story: Know how many small units make one big one (10, 100 or 1000), then multiply to go down or divide to go up.","cta":"Read the story","where":"The Clock Tower · Level 3","level":3,"route":"#/stop/metric-units|story|3"},"moral-metric-units-beat5":{"id":"moral-metric-units-beat5","kind":"moral","src":"story:metric-units#beat5","badge":{"id":"story","label":"A story"},"title":"Rafi, in “The ribbon and the flour”","body":"So the ribbon is 345 cm. Bigger unit to smaller: multiply.","more":"The trick in the story: Know how many small units make one big one (10, 100 or 1000), then multiply to go down or divide to go up.","cta":"Read the story","where":"The Clock Tower · Level 3","level":3,"route":"#/stop/metric-units|story|5"},"try-metric-units-L3":{"id":"try-metric-units-L3","kind":"try","level":3,"src":"try:metric-units@3/1#0","title":"Metres, grams and litres — your turn","where":"The Clock Tower · Level 3","route":"#/stop/metric-units|drill","cta":"Practise this stop","play":{"q":"How many g is 2 kg?","opts":["2000","1000","2001"],"after":"Know how many small units make one big one (10, 100 or 1000), then multiply to go down or divide to go up."}},"trick-perimeter-idea":{"id":"trick-perimeter-idea","kind":"trick","src":"stop:perimeter#idea","title":"Perimeter","body":"Perimeter is the distance all the way round: add every side. A rectangle has two of each side, so double (length + width). Imagine walking round the edge. You walk the length, then the width, then the length again, then the width again — so the perimeter is two lengths and two widths: 2 × (length + width). A square has four sides all the same, so its perimeter is just 4 × the side.","more":"In algebra: rectangle: P = 2(l + w) · L-shape: P = 2(W + H)","cta":"Learn the trick","where":"The Clock Tower · Level 3","level":3,"route":"#/stop/perimeter|learn"},"story-perimeter-open":{"id":"story-perimeter-open","kind":"story","src":"story:perimeter#open","badge":{"id":"story","label":"A story"},"title":"Fencing the vegetable patch","body":"Kwame and Pip are putting a fence round a vegetable patch 8 m long and 5 m wide. — with Kwame and Pip.","more":"The trick inside: Perimeter is the distance all the way round: add every side. A rectangle has two of each side, so double (length + width).","art":"art/s-garden.webp","cta":"Read the story","where":"The Clock Tower · Level 3","level":3,"route":"#/stop/perimeter|story|0"},"idea-perimeter-case0":{"id":"idea-perimeter-case0","kind":"idea","src":"stop:perimeter#case0","title":"Perimeter: A rectangle","body":"Two lengths and two widths. Add one of each, then double it.","more":"The method: Perimeter is the distance all the way round: add every side. A rectangle has two of each side, so double (length + width).","cta":"See it worked","where":"The Clock Tower · Level 3","level":3,"route":"#/stop/perimeter|learn|0"},"idea-perimeter-case1":{"id":"idea-perimeter-case1","kind":"idea","src":"stop:perimeter#case1","title":"Perimeter: A square","body":"Only one side is given, because all four are the same. Four of them make the way round.","more":"The method: Perimeter is the distance all the way round: add every side. A rectangle has two of each side, so double (length + width).","cta":"See it worked","where":"The Clock Tower · Level 3","level":3,"route":"#/stop/perimeter|learn|1"},"idea-perimeter-case2":{"id":"idea-perimeter-case2","kind":"idea","src":"stop:perimeter#case2","title":"Perimeter: An L-shape","body":"Find the two unlabelled sides by taking away. The steps add up to the full width and height, so the answer matches the rectangle around it.","more":"The method: Perimeter is the distance all the way round: add every side. A rectangle has two of each side, so double (length + width).","cta":"See it worked","where":"The Clock Tower · Level 3","level":3,"route":"#/stop/perimeter|learn|2"},"why-perimeter-why2":{"id":"why-perimeter-why2","kind":"why","src":"stop:perimeter#why2","title":"Why “Perimeter” works","body":"So an L-shape (with square corners) has the same perimeter as the rectangle around it: 2 × (full width + full height). Find the missing sides by taking away, add all six, and the rule will agree with you.","more":"The trick: Perimeter is the distance all the way round: add every side. A rectangle has two of each side, so double (length + width).","cta":"See why","where":"The Clock Tower · Level 3","level":3,"route":"#/stop/perimeter|learn"},"moment-perimeter-beat4":{"id":"moment-perimeter-beat4","kind":"moment","src":"story:perimeter#beat4","badge":{"id":"story","label":"A story"},"title":"Fencing the vegetable patch — on the notepad","body":"Kwame: So double it. 2 × 13 = 26","more":"The trick in the story: Perimeter is the distance all the way round: add every side. A rectangle has two of each side, so double (length + width).","cta":"Read the story","where":"The Clock Tower · Level 3","level":3,"route":"#/stop/perimeter|story|4"},"try-perimeter-L3":{"id":"try-perimeter-L3","kind":"try","level":3,"src":"try:perimeter@3/1#0","title":"Perimeter — your turn","where":"The Clock Tower · Level 3","route":"#/stop/perimeter|drill","cta":"Practise this stop","play":{"q":"A rectangle is 5 cm long and 9 cm wide. What is its perimeter, in cm?","opts":["28","14","29"],"after":"Perimeter is the distance all the way round: add every side. A rectangle has two of each side, so double (length + width)."}},"why-fraction-parts-why1":{"id":"why-fraction-parts-why1","kind":"why","src":"stop:fraction-parts#why1","title":"Why “Halves, quarters and thirds” works","body":"The pieces must be equal. Cut a cake into four pieces of different sizes and \"one quarter\" means nothing — somebody got the small one. A half is not just one of two pieces; it is one of two EQUAL pieces.","more":"The trick: Count all the equal pieces for the bottom number, and the shaded pieces for the top.","cta":"See why","where":"The Fraction Bakery · Level 3","level":3,"route":"#/stop/fraction-parts|learn"},"moment-fraction-parts-beat4":{"id":"moment-fraction-parts-beat4","kind":"moment","src":"story:fraction-parts#beat4","badge":{"id":"story","label":"A story"},"title":"The last of the pie — on the notepad","body":"Nova: Then it is three out of four equal slices. Three quarters. 3/4 = 0.75","more":"The trick in the story: Count all the equal pieces for the bottom number, and the shaded pieces for the top.","cta":"Read the story","where":"The Fraction Bakery · Level 3","level":3,"route":"#/stop/fraction-parts|story|4"},"trick-equivalent-fractions-idea":{"id":"trick-equivalent-fractions-idea","kind":"trick","src":"stop:equivalent-fractions#idea","title":"Same share, different pieces","body":"Whatever you do to the bottom, do the same to the top. Cut each quarter of a pie into 3 smaller slices. Now the pie has 12 slices instead of 4 — and your 3 quarters have become 9 slices. You have exactly the same amount of pie; it is just cut smaller.","more":"In algebra: a/b = (a × m)/(b × m)","cta":"Learn the trick","where":"The Fraction Bakery · Level 3","level":3,"route":"#/stop/equivalent-fractions|learn"},"story-equivalent-fractions-open":{"id":"story-equivalent-fractions-open","kind":"story","src":"story:equivalent-fractions#open","badge":{"id":"story","label":"A story"},"title":"Smaller slices","body":"Nova has 3 quarters of a cake. Rafi wants to cut it into twelfths, so more people can have a bite. — with Rafi and Nova.","more":"The trick inside: Whatever you do to the bottom, do the same to the top.","art":"art/s-bakery.webp","cta":"Read the story","where":"The Fraction Bakery · Level 3","level":3,"route":"#/stop/equivalent-fractions|story|0"},"idea-equivalent-fractions-case0":{"id":"idea-equivalent-fractions-case0","kind":"idea","src":"stop:equivalent-fractions#case0","title":"Same share, different pieces: Missing top","body":"Work out what the bottom was multiplied by, then do the same to the top.","more":"The method: Whatever you do to the bottom, do the same to the top.","cta":"See it worked","where":"The Fraction Bakery · Level 3","level":3,"route":"#/stop/equivalent-fractions|learn|0"},"idea-equivalent-fractions-case1":{"id":"idea-equivalent-fractions-case1","kind":"idea","src":"stop:equivalent-fractions#case1","title":"Same share, different pieces: Missing bottom","body":"This time the tops tell you the multiplier. Do the same to the bottom.","more":"The method: Whatever you do to the bottom, do the same to the top.","cta":"See it worked","where":"The Fraction Bakery · Level 3","level":3,"route":"#/stop/equivalent-fractions|learn|1"},"idea-equivalent-fractions-case2":{"id":"idea-equivalent-fractions-case2","kind":"idea","src":"stop:equivalent-fractions#case2","title":"Same share, different pieces: Going down: dividing","body":"The new bottom is smaller, so the pieces are being glued back together: divide the top by the same number.","more":"The method: Whatever you do to the bottom, do the same to the top.","cta":"See it worked","where":"The Fraction Bakery · Level 3","level":3,"route":"#/stop/equivalent-fractions|learn|2"},"why-equivalent-fractions-why1":{"id":"why-equivalent-fractions-why1","kind":"why","src":"stop:equivalent-fractions#why1","title":"Why “Same share, different pieces” works","body":"Cutting every piece into 3 multiplies the number of pieces by 3 (the bottom) AND the number you have by 3 (the top). Both change together, so the fraction stays the same size.","more":"The trick: Whatever you do to the bottom, do the same to the top.","cta":"See why","where":"The Fraction Bakery · Level 3","level":3,"route":"#/stop/equivalent-fractions|learn"},"algebra-equivalent-fractions-alg":{"id":"algebra-equivalent-fractions-alg","kind":"algebra","src":"stop:equivalent-fractions#alg","title":"The algebra behind “Same share, different pieces”","body":"a/b = (a × m)/(b × m)","more":"In words: Whatever you do to the bottom, do the same to the top.","cta":"See why","where":"The Fraction Bakery · Level 3","level":3,"route":"#/stop/equivalent-fractions|learn"},"moral-equivalent-fractions-beat5":{"id":"moral-equivalent-fractions-beat5","kind":"moral","src":"story:equivalent-fractions#beat5","badge":{"id":"story","label":"A story"},"title":"Rafi, in “Smaller slices”","body":"Do the same to the top and the bottom, and the share never changes.","more":"The trick in the story: Whatever you do to the bottom, do the same to the top.","cta":"Read the story","where":"The Fraction Bakery · Level 3","level":3,"route":"#/stop/equivalent-fractions|story|5"},"try-equivalent-fractions-L3":{"id":"try-equivalent-fractions-L3","kind":"try","level":3,"src":"try:equivalent-fractions@3/1#0","title":"Same share, different pieces — your turn","where":"The Fraction Bakery · Level 3","route":"#/stop/equivalent-fractions|drill","cta":"Practise this stop","play":{"q":"3/4 = ?/8 = ?","opts":["6","2","7"],"after":"Whatever you do to the bottom, do the same to the top."}},"trick-compare-fractions-idea":{"id":"trick-compare-fractions-idea","kind":"trick","src":"stop:compare-fractions#idea","title":"Which slice is bigger?","body":"Same bottoms: compare the tops. Same tops: the smaller bottom wins. Otherwise cross-multiply. If the bottoms match, the pieces are the same size, so whoever has more pieces has more: 5/8 is more than 3/8.","more":"In algebra: a/b > c/d  ⇔  a × d > c × b","cta":"Learn the trick","where":"The Fraction Bakery · Level 3","level":3,"route":"#/stop/compare-fractions|learn"},"story-compare-fractions-open":{"id":"story-compare-fractions-open","kind":"story","src":"story:compare-fractions#open","badge":{"id":"story","label":"A story"},"title":"Two birthday cakes","body":"Two cakes at the party, the same size. 3/5 of the lemon cake is left and 4/7 of the chocolate one. — with Theo and Ines.","more":"The trick inside: Same bottoms: compare the tops. Same tops: the smaller bottom wins. Otherwise cross-multiply.","art":"art/s-festival.webp","cta":"Read the story","where":"The Fraction Bakery · Level 3","level":3,"route":"#/stop/compare-fractions|story|0"},"idea-compare-fractions-case0":{"id":"idea-compare-fractions-case0","kind":"idea","src":"stop:compare-fractions#case0","title":"Which slice is bigger?: Same bottoms","body":"Same bottom, same size of piece — so whoever has more pieces has more.","more":"The method: Same bottoms: compare the tops. Same tops: the smaller bottom wins. Otherwise cross-multiply.","cta":"See it worked","where":"The Fraction Bakery · Level 3","level":3,"route":"#/stop/compare-fractions|learn|0"},"idea-compare-fractions-case1":{"id":"idea-compare-fractions-case1","kind":"idea","src":"stop:compare-fractions#case1","title":"Which slice is bigger?: Same tops","body":"The same number of pieces each, so the bigger pieces win — and fewer cuts make bigger pieces. The smaller bottom is more.","more":"The method: Same bottoms: compare the tops. Same tops: the smaller bottom wins. Otherwise cross-multiply.","cta":"See it worked","where":"The Fraction Bakery · Level 3","level":3,"route":"#/stop/compare-fractions|learn|1"},"idea-compare-fractions-case2":{"id":"idea-compare-fractions-case2","kind":"idea","src":"stop:compare-fractions#case2","title":"Which slice is bigger?: Nothing matches","body":"Cross-multiply: each top times the other bottom. Those are the tops you would get with a shared bottom.","more":"The method: Same bottoms: compare the tops. Same tops: the smaller bottom wins. Otherwise cross-multiply.","cta":"See it worked","where":"The Fraction Bakery · Level 3","level":3,"route":"#/stop/compare-fractions|learn|2"},"idea-compare-fractions-case3":{"id":"idea-compare-fractions-case3","kind":"idea","src":"stop:compare-fractions#case3","title":"Which slice is bigger?: Equal after all","body":"Different numbers can name the same share. When the cross-multiplied tops match, the answer is =.","more":"The method: Same bottoms: compare the tops. Same tops: the smaller bottom wins. Otherwise cross-multiply.","cta":"See it worked","where":"The Fraction Bakery · Level 3","level":3,"route":"#/stop/compare-fractions|learn|3"},"why-compare-fractions-why1":{"id":"why-compare-fractions-why1","kind":"why","src":"stop:compare-fractions#why1","title":"Why “Which slice is bigger?” works","body":"If the tops match, you have the same NUMBER of pieces — so the bigger pieces win, and bigger pieces come from cutting into fewer. 2/5 is more than 2/7, because fifths are bigger than sevenths.","more":"The trick: Same bottoms: compare the tops. Same tops: the smaller bottom wins. Otherwise cross-multiply.","cta":"See why","where":"The Fraction Bakery · Level 3","level":3,"route":"#/stop/compare-fractions|learn"},"algebra-compare-fractions-alg":{"id":"algebra-compare-fractions-alg","kind":"algebra","src":"stop:compare-fractions#alg","title":"The algebra behind “Which slice is bigger?”","body":"a/b > c/d  ⇔  a × d > c × b","more":"In words: Same bottoms: compare the tops. Same tops: the smaller bottom wins. Otherwise cross-multiply.","cta":"See why","where":"The Fraction Bakery · Level 3","level":3,"route":"#/stop/compare-fractions|learn"},"moral-compare-fractions-beat6":{"id":"moral-compare-fractions-beat6","kind":"moral","src":"story:compare-fractions#beat6","badge":{"id":"story","label":"A story"},"title":"Theo, in “Two birthday cakes”","body":"I checked the decimals too. Three fifths is a little bigger.","more":"The trick in the story: Same bottoms: compare the tops. Same tops: the smaller bottom wins. Otherwise cross-multiply.","cta":"Read the story","where":"The Fraction Bakery · Level 3","level":3,"route":"#/stop/compare-fractions|story|6"},"try-compare-fractions-L3":{"id":"try-compare-fractions-L3","kind":"try","level":3,"src":"try:compare-fractions@3/1#0","title":"Which slice is bigger? — your turn","where":"The Fraction Bakery · Level 3","route":"#/stop/compare-fractions|drill","cta":"Practise this stop","play":{"q":"2/3  ?  1/3","opts":[">","<","="],"after":"Same bottoms: compare the tops. Same tops: the smaller bottom wins. Otherwise cross-multiply."}},"trick-add-same-bottom-idea":{"id":"trick-add-same-bottom-idea","kind":"trick","src":"stop:add-same-bottom#idea","title":"Adding slices of the same size","body":"When the bottoms match, add or take away the tops. The bottom stays. Sevenths are a SIZE of slice, like \"biscuits\" is a kind of thing. Two biscuits and three biscuits are five biscuits — not five double-biscuits. Two sevenths and three sevenths are five sevenths.","more":"In algebra: a/b ± c/b = (a ± c)/b","cta":"Learn the trick","where":"The Fraction Bakery · Level 3","level":3,"route":"#/stop/add-same-bottom|learn"},"story-add-same-bottom-open":{"id":"story-add-same-bottom-open","kind":"story","src":"story:add-same-bottom#open","badge":{"id":"story","label":"A story"},"title":"Seven-slice pizza","body":"A pizza is cut into 7 equal slices. Dax eats 2 slices, and Nova eats 3. — with Nova and Dax.","more":"The trick inside: When the bottoms match, add or take away the tops. The bottom stays.","art":"art/s-kitchen.webp","cta":"Read the story","where":"The Fraction Bakery · Level 3","level":3,"route":"#/stop/add-same-bottom|story|0"},"hook-add-same-bottom-hook":{"id":"hook-add-same-bottom-hook","kind":"hook","src":"stop:add-same-bottom#hook","title":"Can you? — Adding slices of the same size","body":"2/7 + 3/7 — why is the answer not 5/14?","more":"The way in: When the bottoms match, add or take away the tops. The bottom stays.","cta":"Find out how","where":"The Fraction Bakery · Level 3","level":3,"route":"#/stop/add-same-bottom|learn"},"idea-add-same-bottom-case0":{"id":"idea-add-same-bottom-case0","kind":"idea","src":"stop:add-same-bottom#case0","title":"Adding slices of the same size: Adding","body":"The bottom names the size of the slices, and adding more slices does not change their size. Add the tops only.","more":"The method: When the bottoms match, add or take away the tops. The bottom stays.","cta":"See it worked","where":"The Fraction Bakery · Level 3","level":3,"route":"#/stop/add-same-bottom|learn|0"},"worked-add-same-bottom-worked0":{"id":"worked-add-same-bottom-worked0","kind":"worked","src":"stop:add-same-bottom#worked0","title":"Worked out — Adding slices of the same size: Adding","body":"2/7 + 3/7: Add the tops: 2 + 3 → 5 · Keep the bottom — the pieces are the same size → 5/7","more":"What is special here: The bottom names the size of the slices, and adding more slices does not change their size. Add the tops only.","cta":"Watch it step by step","where":"The Fraction Bakery · Level 3","level":3,"route":"#/stop/add-same-bottom|learn|0"},"idea-add-same-bottom-case1":{"id":"idea-add-same-bottom-case1","kind":"idea","src":"stop:add-same-bottom#case1","title":"Adding slices of the same size: Taking away","body":"Same size of slice again, so take away the tops and keep the bottom just as it is.","more":"The method: When the bottoms match, add or take away the tops. The bottom stays.","cta":"See it worked","where":"The Fraction Bakery · Level 3","level":3,"route":"#/stop/add-same-bottom|learn|1"},"worked-add-same-bottom-worked1":{"id":"worked-add-same-bottom-worked1","kind":"worked","src":"stop:add-same-bottom#worked1","title":"Worked out — Adding slices of the same size: Taking away","body":"5/9 − 2/9: Take the tops: 5 − 2 → 3 · Keep the bottom — the pieces are the same size → 3/9","more":"What is special here: Same size of slice again, so take away the tops and keep the bottom just as it is.","cta":"Watch it step by step","where":"The Fraction Bakery · Level 3","level":3,"route":"#/stop/add-same-bottom|learn|1"},"why-add-same-bottom-why1":{"id":"why-add-same-bottom-why1","kind":"why","src":"stop:add-same-bottom#why1","title":"Why “Adding slices of the same size” works","body":"The bottom number names the size of the pieces, and adding more pieces does not make any piece smaller. So the bottom does not change; only the count on top does.","more":"The trick: When the bottoms match, add or take away the tops. The bottom stays.","cta":"See why","where":"The Fraction Bakery · Level 3","level":3,"route":"#/stop/add-same-bottom|learn"},"why-add-same-bottom-why2":{"id":"why-add-same-bottom-why2","kind":"why","src":"stop:add-same-bottom#why2","title":"Why “Adding slices of the same size” works","body":"Adding the bottoms too (5/14) would mean the pie had been cut into more pieces just because you put two plates together. It had not. Taking away works the same way: 5/9 − 2/9 is 3/9.","more":"The trick: When the bottoms match, add or take away the tops. The bottom stays.","cta":"See why","where":"The Fraction Bakery · Level 3","level":3,"route":"#/stop/add-same-bottom|learn"},"algebra-add-same-bottom-alg":{"id":"algebra-add-same-bottom-alg","kind":"algebra","src":"stop:add-same-bottom#alg","title":"The algebra behind “Adding slices of the same size”","body":"a/b ± c/b = (a ± c)/b","more":"In words: When the bottoms match, add or take away the tops. The bottom stays.","cta":"See why","where":"The Fraction Bakery · Level 3","level":3,"route":"#/stop/add-same-bottom|learn"},"moral-add-same-bottom-beat5":{"id":"moral-add-same-bottom-beat5","kind":"moral","src":"story:add-same-bottom#beat5","badge":{"id":"story","label":"A story"},"title":"Dax, in “Seven-slice pizza”","body":"Five sevenths. The bottom is the size of the slice, and that did not change.","more":"The trick in the story: When the bottoms match, add or take away the tops. The bottom stays.","cta":"Read the story","where":"The Fraction Bakery · Level 3","level":3,"route":"#/stop/add-same-bottom|story|5"},"try-add-same-bottom-L3":{"id":"try-add-same-bottom-L3","kind":"try","level":3,"src":"try:add-same-bottom@3/1#0","title":"Adding slices of the same size — your turn","where":"The Fraction Bakery · Level 3","route":"#/stop/add-same-bottom|drill","cta":"Practise this stop","play":{"q":"1/10 + 9/10 = ?","opts":["10/10","10","11/10"],"after":"When the bottoms match, add or take away the tops. The bottom stays."}},"idea-lines-of-symmetry-case0":{"id":"idea-lines-of-symmetry-case0","kind":"idea","src":"stop:lines-of-symmetry#case0","title":"Lines of symmetry: Folds through middles","body":"A rectangle folds top to bottom and side to side. The diagonal is NOT a fold: the long side would land on the short side.","more":"The method: A line of symmetry is a fold that lands one half exactly on the other — count every fold that works.","cta":"See it worked","where":"Shape City · Level 3","level":3,"route":"#/stop/lines-of-symmetry|learn|0"},"idea-lines-of-symmetry-case3":{"id":"idea-lines-of-symmetry-case3","kind":"idea","src":"stop:lines-of-symmetry#case3","title":"Lines of symmetry: Folds through corners","body":"A kite folds only down its long middle, from corner to corner. Folding it across leaves the top and bottom not matching.","more":"The method: A line of symmetry is a fold that lands one half exactly on the other — count every fold that works.","cta":"See it worked","where":"Shape City · Level 3","level":3,"route":"#/stop/lines-of-symmetry|learn|3"},"why-lines-of-symmetry-why2":{"id":"why-lines-of-symmetry-why2","kind":"why","src":"stop:lines-of-symmetry#why2","title":"Why “Lines of symmetry” works","body":"A rectangle has only two. Fold it corner to corner and the long side lands on the short side, which does not fit — so the diagonal is not a line of symmetry, even though it cuts the rectangle into two equal halves. Some shapes have none at all: a parallelogram or a scalene triangle looks balanced, but every fold leaves a corner hanging over the edge.","more":"The trick: A line of symmetry is a fold that lands one half exactly on the other — count every fold that works.","cta":"See why","where":"Shape City · Level 3","level":3,"route":"#/stop/lines-of-symmetry|learn"},"moral-lines-of-symmetry-beat6":{"id":"moral-lines-of-symmetry-beat6","kind":"moral","src":"story:lines-of-symmetry#beat6","badge":{"id":"story","label":"A story"},"title":"Nova, in “Folding the kite paper”","body":"Two lines of symmetry. Cutting it in equal halves is not enough — the halves must land on each other.","more":"The trick in the story: A line of symmetry is a fold that lands one half exactly on the other — count every fold that works.","cta":"Read the story","where":"Shape City · Level 3","level":3,"route":"#/stop/lines-of-symmetry|story|6"},"trick-faces-edges-vertices-idea":{"id":"trick-faces-edges-vertices-idea","kind":"trick","src":"stop:faces-edges-vertices#idea","title":"Faces, edges and corners","body":"Count by the ends: a prism has two matching ends joined by straight sides; a pyramid has one base and a point. A prism is its end shape pulled straight out. If the end has n sides, there are n edges round the front end, n round the back end, and n running between them: 3n edges. It has 2n corners (called vertices) — n on each end — and n + 2 faces: one for each side, plus the two ends.","more":"In algebra: prism: F = n + 2, E = 3n, V = 2n · pyramid: F = V = n + 1, E = 2n · F + V − E = 2","cta":"Learn the trick","where":"Shape City · Level 3","level":3,"route":"#/stop/faces-edges-vertices|learn"},"story-faces-edges-vertices-open":{"id":"story-faces-edges-vertices-open","kind":"story","src":"story:faces-edges-vertices#open","badge":{"id":"story","label":"A story"},"title":"The paper lanterns","body":"Rafi and Dax are building a hexagonal prism lantern out of straws for the festival. — with Rafi and Dax.","more":"The trick inside: Count by the ends: a prism has two matching ends joined by straight sides; a pyramid has one base and a point.","art":"art/s-festival.webp","cta":"Read the story","where":"Shape City · Level 3","level":3,"route":"#/stop/faces-edges-vertices|story|0"},"hook-faces-edges-vertices-hook":{"id":"hook-faces-edges-vertices-hook","kind":"hook","src":"stop:faces-edges-vertices#hook","title":"Can you? — Faces, edges and corners","body":"A hexagonal prism — how many edges, without losing count?","more":"The way in: Count by the ends: a prism has two matching ends joined by straight sides; a pyramid has one base and a point.","cta":"Find out how","where":"Shape City · Level 3","level":3,"route":"#/stop/faces-edges-vertices|learn"},"idea-faces-edges-vertices-case0":{"id":"idea-faces-edges-vertices-case0","kind":"idea","src":"stop:faces-edges-vertices#case0","title":"Faces, edges and corners: Edges of a prism","body":"Three rings of edges: round the front end, round the back end, and running between them. So 3 × the sides of an end.","more":"The method: Count by the ends: a prism has two matching ends joined by straight sides; a pyramid has one base and a point.","cta":"See it worked","where":"Shape City · Level 3","level":3,"route":"#/stop/faces-edges-vertices|learn|0"},"worked-faces-edges-vertices-worked0":{"id":"worked-faces-edges-vertices-worked0","kind":"worked","src":"stop:faces-edges-vertices#worked0","title":"Worked out — Faces, edges and corners: Edges of a prism","body":"How many edges does a hexagonal prism have?: Edges round the front end → 6 · Round the back end → 6 · Running from end to end → 6 · Edges altogether → 18","more":"What is special here: Three rings of edges: round the front end, round the back end, and running between them. So 3 × the sides of an end.","cta":"Watch it step by step","where":"Shape City · Level 3","level":3,"route":"#/stop/faces-edges-vertices|learn|0"},"idea-faces-edges-vertices-case1":{"id":"idea-faces-edges-vertices-case1","kind":"idea","src":"stop:faces-edges-vertices#case1","title":"Faces, edges and corners: Faces of a prism","body":"One flat side for every side of the end shape — and do not forget the two ends themselves.","more":"The method: Count by the ends: a prism has two matching ends joined by straight sides; a pyramid has one base and a point.","cta":"See it worked","where":"Shape City · Level 3","level":3,"route":"#/stop/faces-edges-vertices|learn|1"},"worked-faces-edges-vertices-worked1":{"id":"worked-faces-edges-vertices-worked1","kind":"worked","src":"stop:faces-edges-vertices#worked1","title":"Worked out — Faces, edges and corners: Faces of a prism","body":"How many faces does a pentagonal prism have?: The two ends → 2 · One flat side for each side of an end → 5 · Faces altogether → 7","more":"What is special here: One flat side for every side of the end shape — and do not forget the two ends themselves.","cta":"Watch it step by step","where":"Shape City · Level 3","level":3,"route":"#/stop/faces-edges-vertices|learn|1"},"idea-faces-edges-vertices-case2":{"id":"idea-faces-edges-vertices-case2","kind":"idea","src":"stop:faces-edges-vertices#case2","title":"Faces, edges and corners: Corners of a prism","body":"All the corners sit on the two ends, so it is twice the corners of one end.","more":"The method: Count by the ends: a prism has two matching ends joined by straight sides; a pyramid has one base and a point.","cta":"See it worked","where":"Shape City · Level 3","level":3,"route":"#/stop/faces-edges-vertices|learn|2"},"worked-faces-edges-vertices-worked2":{"id":"worked-faces-edges-vertices-worked2","kind":"worked","src":"stop:faces-edges-vertices#worked2","title":"Worked out — Faces, edges and corners: Corners of a prism","body":"How many vertices (corners) does a triangular prism have?: Corners on one end → 3 · Corners on both ends → 6","more":"What is special here: All the corners sit on the two ends, so it is twice the corners of one end.","cta":"Watch it step by step","where":"Shape City · Level 3","level":3,"route":"#/stop/faces-edges-vertices|learn|2"},"idea-faces-edges-vertices-case3":{"id":"idea-faces-edges-vertices-case3","kind":"idea","src":"stop:faces-edges-vertices#case3","title":"Faces, edges and corners: Edges of a pyramid","body":"One ring round the base, and one edge from each base corner up to the tip: 2 × the sides of the base.","more":"The method: Count by the ends: a prism has two matching ends joined by straight sides; a pyramid has one base and a point.","cta":"See it worked","where":"Shape City · Level 3","level":3,"route":"#/stop/faces-edges-vertices|learn|3"},"worked-faces-edges-vertices-worked3":{"id":"worked-faces-edges-vertices-worked3","kind":"worked","src":"stop:faces-edges-vertices#worked3","title":"Worked out — Faces, edges and corners: Edges of a pyramid","body":"How many edges does a square-based pyramid have?: Edges round the base → 4 · Edges up to the tip → 4 · Edges altogether → 8","more":"What is special here: One ring round the base, and one edge from each base corner up to the tip: 2 × the sides of the base.","cta":"Watch it step by step","where":"Shape City · Level 3","level":3,"route":"#/stop/faces-edges-vertices|learn|3"},"idea-faces-edges-vertices-case4":{"id":"idea-faces-edges-vertices-case4","kind":"idea","src":"stop:faces-edges-vertices#case4","title":"Faces, edges and corners: Faces of a pyramid","body":"A triangle leans in from every side of the base — plus the base, which is easy to forget because it is underneath.","more":"The method: Count by the ends: a prism has two matching ends joined by straight sides; a pyramid has one base and a point.","cta":"See it worked","where":"Shape City · Level 3","level":3,"route":"#/stop/faces-edges-vertices|learn|4"},"worked-faces-edges-vertices-worked4":{"id":"worked-faces-edges-vertices-worked4","kind":"worked","src":"stop:faces-edges-vertices#worked4","title":"Worked out — Faces, edges and corners: Faces of a pyramid","body":"How many faces does a pentagonal pyramid have?: The base → 1 · One triangle for each side of the base → 5 · Faces altogether → 6","more":"What is special here: A triangle leans in from every side of the base — plus the base, which is easy to forget because it is underneath.","cta":"Watch it step by step","where":"Shape City · Level 3","level":3,"route":"#/stop/faces-edges-vertices|learn|4"},"idea-faces-edges-vertices-case5":{"id":"idea-faces-edges-vertices-case5","kind":"idea","src":"stop:faces-edges-vertices#case5","title":"Faces, edges and corners: Corners of a pyramid","body":"The corners of the base, and then the tip on top: one more than the base has.","more":"The method: Count by the ends: a prism has two matching ends joined by straight sides; a pyramid has one base and a point.","cta":"See it worked","where":"Shape City · Level 3","level":3,"route":"#/stop/faces-edges-vertices|learn|5"},"worked-faces-edges-vertices-worked5":{"id":"worked-faces-edges-vertices-worked5","kind":"worked","src":"stop:faces-edges-vertices#worked5","title":"Worked out — Faces, edges and corners: Corners of a pyramid","body":"How many vertices (corners) does a hexagonal pyramid have?: Corners of the base → 6 · Add the tip → 7","more":"What is special here: The corners of the base, and then the tip on top: one more than the base has.","cta":"Watch it step by step","where":"Shape City · Level 3","level":3,"route":"#/stop/faces-edges-vertices|learn|5"},"idea-faces-edges-vertices-case6":{"id":"idea-faces-edges-vertices-case6","kind":"idea","src":"stop:faces-edges-vertices#case6","title":"Faces, edges and corners: Edges by Euler's rule","body":"No picture and no name — just two counts. Faces + vertices − edges is always 2, so the edges are 2 fewer than faces + vertices.","more":"The method: Count by the ends: a prism has two matching ends joined by straight sides; a pyramid has one base and a point.","cta":"See it worked","where":"Shape City · Level 3","level":3,"route":"#/stop/faces-edges-vertices|learn|6"},"worked-faces-edges-vertices-worked6":{"id":"worked-faces-edges-vertices-worked6","kind":"worked","src":"stop:faces-edges-vertices#worked6","title":"Worked out — Faces, edges and corners: Edges by Euler's rule","body":"A solid has 7 faces and 10 vertices (corners). Use Euler's rule: how many edges does it have?: Faces + vertices: 7 + 10 → 17 · Edges are 2 fewer than that → 15","more":"What is special here: No picture and no name — just two counts. Faces + vertices − edges is always 2, so the edges are 2 fewer than faces + vertices.","cta":"Watch it step by step","where":"Shape City · Level 3","level":3,"route":"#/stop/faces-edges-vertices|learn|6"},"why-faces-edges-vertices-why1":{"id":"why-faces-edges-vertices-why1","kind":"why","src":"stop:faces-edges-vertices#why1","title":"Why “Faces, edges and corners” works","body":"A pyramid is its base shape pulled up to a single point. It has n edges round the base and n running up to the tip: 2n. It has n + 1 vertices (the base corners and the tip) and n + 1 faces (a triangle for every side of the base, and the base).","more":"The trick: Count by the ends: a prism has two matching ends joined by straight sides; a pyramid has one base and a point.","cta":"See why","where":"Shape City · Level 3","level":3,"route":"#/stop/faces-edges-vertices|learn"},"why-faces-edges-vertices-why2":{"id":"why-faces-edges-vertices-why2","kind":"why","src":"stop:faces-edges-vertices#why2","title":"Why “Faces, edges and corners” works","body":"For every solid like these, faces + vertices − edges = 2. That is Euler's rule, and it is the best check there is: count all three, and if the rule does not give 2, you have missed something.","more":"The trick: Count by the ends: a prism has two matching ends joined by straight sides; a pyramid has one base and a point.","cta":"See why","where":"Shape City · Level 3","level":3,"route":"#/stop/faces-edges-vertices|learn"},"algebra-faces-edges-vertices-alg":{"id":"algebra-faces-edges-vertices-alg","kind":"algebra","src":"stop:faces-edges-vertices#alg","title":"The algebra behind “Faces, edges and corners”","body":"prism: F = n + 2, E = 3n, V = 2n · pyramid: F = V = n + 1, E = 2n · F + V − E = 2","more":"In words: Count by the ends: a prism has two matching ends joined by straight sides; a pyramid has one base and a point.","cta":"See why","where":"Shape City · Level 3","level":3,"route":"#/stop/faces-edges-vertices|learn"},"moment-faces-edges-vertices-beat3":{"id":"moment-faces-edges-vertices-beat3","kind":"moment","src":"story:faces-edges-vertices#beat3","badge":{"id":"story","label":"A story"},"title":"The paper lanterns — on the notepad","body":"Dax: Round the back one, another 6. Then 6 joining the ends. 6 + 6 + 6 = 18","more":"The trick in the story: Count by the ends: a prism has two matching ends joined by straight sides; a pyramid has one base and a point.","cta":"Read the story","where":"Shape City · Level 3","level":3,"route":"#/stop/faces-edges-vertices|story|3"},"moral-faces-edges-vertices-beat5":{"id":"moral-faces-edges-vertices-beat5","kind":"moral","src":"story:faces-edges-vertices#beat5","badge":{"id":"story","label":"A story"},"title":"Dax, in “The paper lanterns”","body":"Eighteen straws. The rule agrees — so we did not miss one.","more":"The trick in the story: Count by the ends: a prism has two matching ends joined by straight sides; a pyramid has one base and a point.","cta":"Read the story","where":"Shape City · Level 3","level":3,"route":"#/stop/faces-edges-vertices|story|5"},"try-faces-edges-vertices-L3":{"id":"try-faces-edges-vertices-L3","kind":"try","level":3,"src":"try:faces-edges-vertices@3/1#0","title":"Faces, edges and corners — your turn","where":"Shape City · Level 3","route":"#/stop/faces-edges-vertices|drill","cta":"Practise this stop","play":{"q":"How many faces does a triangular prism have?","opts":["5","2","3"],"after":"Count by the ends: a prism has two matching ends joined by straight sides; a pyramid has one base and a point."}},"trick-kinds-of-angle-idea":{"id":"trick-kinds-of-angle-idea","kind":"trick","src":"stop:kinds-of-angle#idea","title":"Kinds of angle","body":"Compare the angle with a square corner (90°) and a straight line (180°). An angle measures how far something turns. A whole turn is 360°, so half a turn — a straight line — is 180°, and a quarter turn — the corner of a page — is 90°, a right angle.","more":"In algebra: acute < 90° = right < obtuse < 180° < reflex < 360°","cta":"Learn the trick","where":"Shape City · Level 3","level":3,"route":"#/stop/kinds-of-angle|learn"},"story-kinds-of-angle-open":{"id":"story-kinds-of-angle-open","kind":"story","src":"story:kinds-of-angle#open","badge":{"id":"story","label":"A story"},"title":"The opening door","body":"The hall door swings open. Pip and Suki watch the angle between the door and the wall. — with Pip and Suki.","more":"The trick inside: Compare the angle with a square corner (90°) and a straight line (180°).","art":"art/s-hall.webp","cta":"Read the story","where":"Shape City · Level 3","level":3,"route":"#/stop/kinds-of-angle|story|0"},"hook-kinds-of-angle-hook":{"id":"hook-kinds-of-angle-hook","kind":"hook","src":"stop:kinds-of-angle#hook","title":"Can you? — Kinds of angle","body":"Is this corner sharp, square, wide, or more than half a turn?","more":"The way in: Compare the angle with a square corner (90°) and a straight line (180°).","cta":"Find out how","where":"Shape City · Level 3","level":3,"route":"#/stop/kinds-of-angle|learn"},"idea-kinds-of-angle-case0":{"id":"idea-kinds-of-angle-case0","kind":"idea","src":"stop:kinds-of-angle#case0","title":"Kinds of angle: Acute","body":"It fits inside the corner of a page with room to spare: smaller than a right angle. Acute means sharp.","more":"The method: Compare the angle with a square corner (90°) and a straight line (180°).","cta":"See it worked","where":"Shape City · Level 3","level":3,"route":"#/stop/kinds-of-angle|learn|0"},"idea-kinds-of-angle-case1":{"id":"idea-kinds-of-angle-case1","kind":"idea","src":"stop:kinds-of-angle#case1","title":"Kinds of angle: Right","body":"Exactly a quarter turn, 90° — the corner of a page fits it perfectly. Not a little more, not a little less.","more":"The method: Compare the angle with a square corner (90°) and a straight line (180°).","cta":"See it worked","where":"Shape City · Level 3","level":3,"route":"#/stop/kinds-of-angle|learn|1"},"idea-kinds-of-angle-case2":{"id":"idea-kinds-of-angle-case2","kind":"idea","src":"stop:kinds-of-angle#case2","title":"Kinds of angle: Obtuse","body":"It pokes out past the corner of a page, but has not yet opened as wide as a straight line. Obtuse means blunt.","more":"The method: Compare the angle with a square corner (90°) and a straight line (180°).","cta":"See it worked","where":"Shape City · Level 3","level":3,"route":"#/stop/kinds-of-angle|learn|2"},"idea-kinds-of-angle-case3":{"id":"idea-kinds-of-angle-case3","kind":"idea","src":"stop:kinds-of-angle#case3","title":"Kinds of angle: Reflex","body":"It has turned past a straight line (180°). Look at which side the arc is on — it is the big, outside angle.","more":"The method: Compare the angle with a square corner (90°) and a straight line (180°).","cta":"See it worked","where":"Shape City · Level 3","level":3,"route":"#/stop/kinds-of-angle|learn|3"},"why-kinds-of-angle-why1":{"id":"why-kinds-of-angle-why1","kind":"why","src":"stop:kinds-of-angle#why1","title":"Why “Kinds of angle” works","body":"Every angle names itself by where it sits against those two. Smaller than a right angle is acute (sharp). Exactly 90° is right. Between 90° and 180° is obtuse (blunt). More than a straight line, but less than a full turn, is reflex.","more":"The trick: Compare the angle with a square corner (90°) and a straight line (180°).","cta":"See why","where":"Shape City · Level 3","level":3,"route":"#/stop/kinds-of-angle|learn"},"why-kinds-of-angle-why2":{"id":"why-kinds-of-angle-why2","kind":"why","src":"stop:kinds-of-angle#why2","title":"Why “Kinds of angle” works","body":"So you never need a protractor to name an angle. Hold the corner of a page against it: if the angle fits inside the corner it is acute; if it pokes out, check whether it has gone past the straight line.","more":"The trick: Compare the angle with a square corner (90°) and a straight line (180°).","cta":"See why","where":"Shape City · Level 3","level":3,"route":"#/stop/kinds-of-angle|learn"},"algebra-kinds-of-angle-alg":{"id":"algebra-kinds-of-angle-alg","kind":"algebra","src":"stop:kinds-of-angle#alg","title":"The algebra behind “Kinds of angle”","body":"acute < 90° = right < obtuse < 180° < reflex < 360°","more":"In words: Compare the angle with a square corner (90°) and a straight line (180°).","cta":"See why","where":"Shape City · Level 3","level":3,"route":"#/stop/kinds-of-angle|learn"},"moment-kinds-of-angle-beat4":{"id":"moment-kinds-of-angle-beat4","kind":"moment","src":"story:kinds-of-angle#beat4","badge":{"id":"story","label":"A story"},"title":"The opening door — on the notepad","body":"Suki: Flat is a straight line, two right angles. 90 + 90 = 180","more":"The trick in the story: Compare the angle with a square corner (90°) and a straight line (180°).","cta":"Read the story","where":"Shape City · Level 3","level":3,"route":"#/stop/kinds-of-angle|story|4"},"moral-kinds-of-angle-beat5":{"id":"moral-kinds-of-angle-beat5","kind":"moral","src":"story:kinds-of-angle#beat5","badge":{"id":"story","label":"A story"},"title":"Pip, in “The opening door”","body":"And if a door could swing past flat, that would be a reflex angle — more than 180° but less than a full turn.","more":"The trick in the story: Compare the angle with a square corner (90°) and a straight line (180°).","cta":"Read the story","where":"Shape City · Level 3","level":3,"route":"#/stop/kinds-of-angle|story|5"},"trick-round-add-idea":{"id":"trick-round-add-idea","kind":"trick","src":"stop:round-add#idea","title":"Round it, then fix it","body":"Add a round number instead, then give back what you added too much. 38 is 40 with 2 missing. Adding 40 is easy, but it adds 2 more than you wanted.","more":"In algebra: a + (10k − d) = (a + 10k) − d","cta":"Learn the trick","where":"The Mental Workshop · Level 3","level":3,"route":"#/stop/round-add|learn"},"story-round-add-open":{"id":"story-round-add-open","kind":"story","src":"story:round-add#open","badge":{"id":"story","label":"A story"},"title":"The money box","body":"Dax has saved 47 coins. His grandmother gives him 38 more. — with Dax and Suki.","more":"The trick inside: Add a round number instead, then give back what you added too much.","art":"art/s-kitchen.webp","cta":"Read the story","where":"The Mental Workshop · Level 3","level":3,"route":"#/stop/round-add|story|0"},"hook-round-add-hook":{"id":"hook-round-add-hook","kind":"hook","src":"stop:round-add#hook","title":"Can you? — Round it, then fix it","body":"47 + 38 — 38 is nearly 40.","more":"The way in: Add a round number instead, then give back what you added too much.","cta":"Find out how","where":"The Mental Workshop · Level 3","level":3,"route":"#/stop/round-add|learn"},"worked-round-add-worked0":{"id":"worked-round-add-worked0","kind":"worked","src":"stop:round-add#worked0","title":"Worked out — Round it, then fix it","body":"47 + 38: 47 + 40 → 87 · Give back 2 → 85","more":"The method: Add a round number instead, then give back what you added too much.","cta":"Watch it step by step","where":"The Mental Workshop · Level 3","level":3,"route":"#/stop/round-add|learn|0"},"why-round-add-why1":{"id":"why-round-add-why1","kind":"why","src":"stop:round-add#why1","title":"Why “Round it, then fix it” works","body":"So take those 2 back off at the end. This is called compensation, and people who are quick at sums do it without noticing.","more":"The trick: Add a round number instead, then give back what you added too much.","cta":"See why","where":"The Mental Workshop · Level 3","level":3,"route":"#/stop/round-add|learn"},"algebra-round-add-alg":{"id":"algebra-round-add-alg","kind":"algebra","src":"stop:round-add#alg","title":"The algebra behind “Round it, then fix it”","body":"a + (10k − d) = (a + 10k) − d","more":"In words: Add a round number instead, then give back what you added too much.","cta":"See why","where":"The Mental Workshop · Level 3","level":3,"route":"#/stop/round-add|learn"},"moment-round-add-beat3":{"id":"moment-round-add-beat3","kind":"moment","src":"story:round-add#beat3","badge":{"id":"story","label":"A story"},"title":"The money box — on the notepad","body":"Suki: So you added 2 too many. Give them back. 87 − 2 = 85","more":"The trick in the story: Add a round number instead, then give back what you added too much.","cta":"Read the story","where":"The Mental Workshop · Level 3","level":3,"route":"#/stop/round-add|story|3"},"moral-round-add-beat4":{"id":"moral-round-add-beat4","kind":"moral","src":"story:round-add#beat4","badge":{"id":"story","label":"A story"},"title":"Dax, in “The money box”","body":"Eighty-five. Round it, then fix it.","more":"The trick in the story: Add a round number instead, then give back what you added too much.","cta":"Read the story","where":"The Mental Workshop · Level 3","level":3,"route":"#/stop/round-add|story|4"},"try-round-add-L3":{"id":"try-round-add-L3","kind":"try","level":3,"src":"try:round-add@3/1#0","title":"Round it, then fix it — your turn","where":"The Mental Workshop · Level 3","route":"#/stop/round-add|drill","cta":"Practise this stop","play":{"q":"12 + 17 = ?","opts":["29","32","30"],"after":"Add a round number instead, then give back what you added too much."}},"trick-round-sub-idea":{"id":"trick-round-sub-idea","kind":"trick","src":"stop:round-sub#idea","title":"Take too much, give it back","body":"Take away the round number, then add back the extra you took. Taking away 30 takes one more than 29. So you have taken too much — by exactly one.","more":"In algebra: a − (10k − d) = (a − 10k) + d","cta":"Learn the trick","where":"The Mental Workshop · Level 3","level":3,"route":"#/stop/round-sub|learn"},"story-round-sub-open":{"id":"story-round-sub-open","kind":"story","src":"story:round-sub#open","badge":{"id":"story","label":"A story"},"title":"Stepping stones","body":"There are 83 stepping stones across the pond. Ines has hopped across 29. — with Ines and Theo.","more":"The trick inside: Take away the round number, then add back the extra you took.","art":"art/s-pond.webp","cta":"Read the story","where":"The Mental Workshop · Level 3","level":3,"route":"#/stop/round-sub|story|0"},"hook-round-sub-hook":{"id":"hook-round-sub-hook","kind":"hook","src":"stop:round-sub#hook","title":"Can you? — Take too much, give it back","body":"83 − 29 — 29 is nearly 30.","more":"The way in: Take away the round number, then add back the extra you took.","cta":"Find out how","where":"The Mental Workshop · Level 3","level":3,"route":"#/stop/round-sub|learn"},"worked-round-sub-worked0":{"id":"worked-round-sub-worked0","kind":"worked","src":"stop:round-sub#worked0","title":"Worked out — Take too much, give it back","body":"83 − 29: 83 − 30 → 53 · Add back 1 → 54","more":"The method: Take away the round number, then add back the extra you took.","cta":"Watch it step by step","where":"The Mental Workshop · Level 3","level":3,"route":"#/stop/round-sub|learn|0"},"why-round-sub-why1":{"id":"why-round-sub-why1","kind":"why","src":"stop:round-sub#why1","title":"Why “Take too much, give it back” works","body":"Put it back. This is the same trick as rounding when you add, run backwards.","more":"The trick: Take away the round number, then add back the extra you took.","cta":"See why","where":"The Mental Workshop · Level 3","level":3,"route":"#/stop/round-sub|learn"},"moment-round-sub-beat3":{"id":"moment-round-sub-beat3","kind":"moment","src":"story:round-sub#beat3","badge":{"id":"story","label":"A story"},"title":"Stepping stones — on the notepad","body":"Ines: We took one stone too many — put it back. 53 + 1 = 54","more":"The trick in the story: Take away the round number, then add back the extra you took.","cta":"Read the story","where":"The Mental Workshop · Level 3","level":3,"route":"#/stop/round-sub|story|3"},"moral-round-sub-beat4":{"id":"moral-round-sub-beat4","kind":"moral","src":"story:round-sub#beat4","badge":{"id":"story","label":"A story"},"title":"Theo, in “Stepping stones”","body":"Fifty-four to go. And I checked it backwards.","more":"The trick in the story: Take away the round number, then add back the extra you took.","cta":"Read the story","where":"The Mental Workshop · Level 3","level":3,"route":"#/stop/round-sub|story|4"},"try-round-sub-L3":{"id":"try-round-sub-L3","kind":"try","level":3,"src":"try:round-sub@3/1#0","title":"Take too much, give it back — your turn","where":"The Mental Workshop · Level 3","route":"#/stop/round-sub|drill","cta":"Practise this stop","play":{"q":"51 − 28 = ?","opts":["23","21","24"],"after":"Take away the round number, then add back the extra you took."}},"trick-split-multiply-idea":{"id":"trick-split-multiply-idea","kind":"trick","src":"stop:split-multiply#idea","title":"Split and multiply","body":"Split 46 into 40 and 6. Multiply each by 7, then add. Seven lots of 46 is seven lots of 40 and seven lots of 6.","more":"In algebra: a × (10t + u) = a × 10t + a × u","cta":"Learn the trick","where":"The Mental Workshop · Level 3","level":3,"route":"#/stop/split-multiply|learn"},"story-split-multiply-open":{"id":"story-split-multiply-open","kind":"story","src":"story:split-multiply#open","badge":{"id":"story","label":"A story"},"title":"The bake sale","body":"For the bake sale there are 7 tins, with 46 biscuits in each. — with Rafi and Nova.","more":"The trick inside: Split 46 into 40 and 6. Multiply each by 7, then add.","art":"art/s-kitchen.webp","cta":"Read the story","where":"The Mental Workshop · Level 3","level":3,"route":"#/stop/split-multiply|story|0"},"hook-split-multiply-hook":{"id":"hook-split-multiply-hook","kind":"hook","src":"stop:split-multiply#hook","title":"Can you? — Split and multiply","body":"7 × 46 — bigger than the times table.","more":"The way in: Split 46 into 40 and 6. Multiply each by 7, then add.","cta":"Find out how","where":"The Mental Workshop · Level 3","level":3,"route":"#/stop/split-multiply|learn"},"worked-split-multiply-worked0":{"id":"worked-split-multiply-worked0","kind":"worked","src":"stop:split-multiply#worked0","title":"Worked out — Split and multiply","body":"7 × 46: 7 × 40 → 280 · 7 × 6 → 42 · Add them → 322","more":"The method: Split 46 into 40 and 6. Multiply each by 7, then add.","cta":"Watch it step by step","where":"The Mental Workshop · Level 3","level":3,"route":"#/stop/split-multiply|learn|0"},"why-split-multiply-why1":{"id":"why-split-multiply-why1","kind":"why","src":"stop:split-multiply#why1","title":"Why “Split and multiply” works","body":"As a picture it is a rectangle 7 by 46, cut into a 7-by-40 piece and a 7-by-6 piece. The areas add up to the whole.","more":"The trick: Split 46 into 40 and 6. Multiply each by 7, then add.","cta":"See why","where":"The Mental Workshop · Level 3","level":3,"route":"#/stop/split-multiply|learn"},"algebra-split-multiply-alg":{"id":"algebra-split-multiply-alg","kind":"algebra","src":"stop:split-multiply#alg","title":"The algebra behind “Split and multiply”","body":"a × (10t + u) = a × 10t + a × u","more":"In words: Split 46 into 40 and 6. Multiply each by 7, then add.","cta":"See why","where":"The Mental Workshop · Level 3","level":3,"route":"#/stop/split-multiply|learn"},"moment-split-multiply-beat3":{"id":"moment-split-multiply-beat3","kind":"moment","src":"story:split-multiply#beat3","badge":{"id":"story","label":"A story"},"title":"The bake sale — on the notepad","body":"Nova: Then seven sixes. 7 × 6 = 42","more":"The trick in the story: Split 46 into 40 and 6. Multiply each by 7, then add.","cta":"Read the story","where":"The Mental Workshop · Level 3","level":3,"route":"#/stop/split-multiply|story|3"},"moral-split-multiply-beat5":{"id":"moral-split-multiply-beat5","kind":"moral","src":"story:split-multiply#beat5","badge":{"id":"story","label":"A story"},"title":"Nova, in “The bake sale”","body":"322 biscuits. Like cutting one big tray into two easy trays.","more":"The trick in the story: Split 46 into 40 and 6. Multiply each by 7, then add.","cta":"Read the story","where":"The Mental Workshop · Level 3","level":3,"route":"#/stop/split-multiply|story|5"},"try-split-multiply-L3":{"id":"try-split-multiply-L3","kind":"try","level":3,"src":"try:split-multiply@3/1#0","title":"Split and multiply — your turn","where":"The Mental Workshop · Level 3","route":"#/stop/split-multiply|drill","cta":"Practise this stop","play":{"q":"7 × 23 = ?","opts":["161","140","21"],"after":"Split 46 into 40 and 6. Multiply each by 7, then add."}},"trick-multiples-idea":{"id":"trick-multiples-idea","kind":"trick","src":"stop:multiples#idea","title":"The next multiple","body":"Divide to see how many whole groups fit, then take one group more. The multiples of 6 are the 6 times table carried on for ever: 6, 12, 18, 24… They are exactly the numbers you can make from whole groups of 6.","more":"In algebra: first multiple of k above s = k × (⌊s ÷ k⌋ + 1)","cta":"Learn the trick","where":"The Factor Forest · Level 3","level":3,"route":"#/stop/multiples|learn"},"story-multiples-open":{"id":"story-multiples-open","kind":"story","src":"story:multiples#open","badge":{"id":"story","label":"A story"},"title":"Boxes of eggs","body":"Nova’s class needs more than 50 eggs for the baking day. Eggs come in boxes of 6. — with Nova and Dax.","more":"The trick inside: Divide to see how many whole groups fit, then take one group more.","art":"art/s-market.webp","cta":"Read the story","where":"The Factor Forest · Level 3","level":3,"route":"#/stop/multiples|story|0"},"idea-multiples-case0":{"id":"idea-multiples-case0","kind":"idea","src":"stop:multiples#case0","title":"The next multiple: Some left over","body":"The whole groups stop just short of the number, so one group more is the first multiple past it.","more":"The method: Divide to see how many whole groups fit, then take one group more.","cta":"See it worked","where":"The Factor Forest · Level 3","level":3,"route":"#/stop/multiples|learn|0"},"idea-multiples-case1":{"id":"idea-multiples-case1","kind":"idea","src":"stop:multiples#case1","title":"The next multiple: It fits exactly","body":"The trap: 48 is already 8 sixes, but it is not BIGGER than 48. Still take one group more.","more":"The method: Divide to see how many whole groups fit, then take one group more.","cta":"See it worked","where":"The Factor Forest · Level 3","level":3,"route":"#/stop/multiples|learn|1"},"why-multiples-why1":{"id":"why-multiples-why1","kind":"why","src":"stop:multiples#why1","title":"Why “The next multiple” works","body":"To find the first one past 50, you do not have to count up from 6. 50 ÷ 6 is 8, with some left over, so 8 boxes — 48 eggs — is the most that stays at or under 50. One more box is the first multiple past it: 9 × 6 = 54. And if the number is already a multiple — 48 is exactly 8 boxes — you still take one box more, because the question wants a number BIGGER than 48.","more":"The trick: Divide to see how many whole groups fit, then take one group more.","cta":"See why","where":"The Factor Forest · Level 3","level":3,"route":"#/stop/multiples|learn"},"algebra-multiples-alg":{"id":"algebra-multiples-alg","kind":"algebra","src":"stop:multiples#alg","title":"The algebra behind “The next multiple”","body":"first multiple of k above s = k × (⌊s ÷ k⌋ + 1)","more":"In words: Divide to see how many whole groups fit, then take one group more.","cta":"See why","where":"The Factor Forest · Level 3","level":3,"route":"#/stop/multiples|learn"},"moral-multiples-beat5":{"id":"moral-multiples-beat5","kind":"moral","src":"story:multiples#beat5","badge":{"id":"story","label":"A story"},"title":"Dax, in “Boxes of eggs”","body":"Nine boxes: 54 eggs. The first multiple of 6 over 50.","more":"The trick in the story: Divide to see how many whole groups fit, then take one group more.","cta":"Read the story","where":"The Factor Forest · Level 3","level":3,"route":"#/stop/multiples|story|5"},"try-multiples-L3":{"id":"try-multiples-L3","kind":"try","level":3,"src":"try:multiples@3/1#0","title":"The next multiple — your turn","where":"The Factor Forest · Level 3","route":"#/stop/multiples|drill","cta":"Practise this stop","play":{"q":"What is the first multiple of 2 bigger than 40?","opts":["42","20","21"],"after":"Divide to see how many whole groups fit, then take one group more."}},"trick-divisible-2-5-10-idea":{"id":"trick-divisible-2-5-10-idea","kind":"trick","src":"stop:divisible-2-5-10#idea","title":"Tests for 2, 5 and 10","body":"Look at the last digit only. Even for 2; 0 or 5 for 5; 0 for 10. Split any number into its tens and its last digit: 3,475 is 3,470 + 5. The 3,470 is a whole number of tens, and every ten can be split into two fives, or five twos. So that big part always divides by 2, 5 and 10 — whatever it is.","more":"In algebra: n = 10a + b, and 2, 5, 10 all divide 10a ⇒ test b","cta":"Learn the trick","where":"The Factor Forest · Level 3","level":3,"route":"#/stop/divisible-2-5-10|learn"},"story-divisible-2-5-10-open":{"id":"story-divisible-2-5-10-open","kind":"story","src":"story:divisible-2-5-10#open","badge":{"id":"story","label":"A story"},"title":"Bracelets of five","body":"Pip has 3,475 beads, and wants to thread every one onto bracelets of 5 beads each. — with Ines and Pip.","more":"The trick inside: Look at the last digit only. Even for 2; 0 or 5 for 5; 0 for 10.","art":"art/s-room.webp","cta":"Read the story","where":"The Factor Forest · Level 3","level":3,"route":"#/stop/divisible-2-5-10|story|0"},"idea-divisible-2-5-10-case0":{"id":"idea-divisible-2-5-10-case0","kind":"idea","src":"stop:divisible-2-5-10#case0","title":"Tests for 2, 5 and 10: Divisible by 2","body":"The last digit must be even — 0, 2, 4, 6 or 8. Nothing else in the number can spoil it.","more":"The method: Look at the last digit only. Even for 2; 0 or 5 for 5; 0 for 10.","cta":"See it worked","where":"The Factor Forest · Level 3","level":3,"route":"#/stop/divisible-2-5-10|learn|0"},"idea-divisible-2-5-10-case1":{"id":"idea-divisible-2-5-10-case1","kind":"idea","src":"stop:divisible-2-5-10#case1","title":"Tests for 2, 5 and 10: Divisible by 5","body":"The last digit must be 0 or 5, because those are the only single digits that split into fives.","more":"The method: Look at the last digit only. Even for 2; 0 or 5 for 5; 0 for 10.","cta":"See it worked","where":"The Factor Forest · Level 3","level":3,"route":"#/stop/divisible-2-5-10|learn|1"},"idea-divisible-2-5-10-case2":{"id":"idea-divisible-2-5-10-case2","kind":"idea","src":"stop:divisible-2-5-10#case2","title":"Tests for 2, 5 and 10: Divisible by 10","body":"The last digit must be 0. A 5 on the end is enough for five, but not for ten.","more":"The method: Look at the last digit only. Even for 2; 0 or 5 for 5; 0 for 10.","cta":"See it worked","where":"The Factor Forest · Level 3","level":3,"route":"#/stop/divisible-2-5-10|learn|2"},"why-divisible-2-5-10-why1":{"id":"why-divisible-2-5-10-why1","kind":"why","src":"stop:divisible-2-5-10#why1","title":"Why “Tests for 2, 5 and 10” works","body":"That leaves only the last digit to decide. 5 divides by 5, so 3,475 does too. It is odd, so 3,475 will not halve; and it is not 0, so it is not a whole number of tens.","more":"The trick: Look at the last digit only. Even for 2; 0 or 5 for 5; 0 for 10.","cta":"See why","where":"The Factor Forest · Level 3","level":3,"route":"#/stop/divisible-2-5-10|learn"},"algebra-divisible-2-5-10-alg":{"id":"algebra-divisible-2-5-10-alg","kind":"algebra","src":"stop:divisible-2-5-10#alg","title":"The algebra behind “Tests for 2, 5 and 10”","body":"n = 10a + b, and 2, 5, 10 all divide 10a ⇒ test b","more":"In words: Look at the last digit only. Even for 2; 0 or 5 for 5; 0 for 10.","cta":"See why","where":"The Factor Forest · Level 3","level":3,"route":"#/stop/divisible-2-5-10|learn"},"moral-divisible-2-5-10-beat5":{"id":"moral-divisible-2-5-10-beat5","kind":"moral","src":"story:divisible-2-5-10#beat5","badge":{"id":"story","label":"A story"},"title":"Ines, in “Bracelets of five”","body":"Last digit 0 or 5: yes for five. Even: yes for two. A 0: yes for ten.","more":"The trick in the story: Look at the last digit only. Even for 2; 0 or 5 for 5; 0 for 10.","cta":"Read the story","where":"The Factor Forest · Level 3","level":3,"route":"#/stop/divisible-2-5-10|story|5"},"try-divisible-2-5-10-L3":{"id":"try-divisible-2-5-10-L3","kind":"try","level":3,"src":"try:divisible-2-5-10@3/1#0","title":"Tests for 2, 5 and 10 — your turn","where":"The Factor Forest · Level 3","route":"#/stop/divisible-2-5-10|drill","cta":"Practise this stop","play":{"q":"Is 351 divisible by 2?","opts":["No","Yes"],"after":"Look at the last digit only. Even for 2; 0 or 5 for 5; 0 for 10."}},"trick-odd-even-rules-idea":{"id":"trick-odd-even-rules-idea","kind":"trick","src":"stop:odd-even-rules#idea","title":"Odd and even rules","body":"Only whether each number is odd or even matters. Even ± even and odd ± odd are even; odd ± even is odd. A product is even if any number in it is even. An even number is one that stands in pairs with nobody left over. An odd number is pairs and ONE extra. Picture 37 children in pairs: 18 pairs and one child alone. 58 children make 29 pairs and nobody alone.","more":"In algebra: even ± even = even · odd ± odd = even · odd ± even = odd · odd × odd = odd, anything × even = even","cta":"Learn the trick","where":"The Prime Quarry · Level 3","level":3,"route":"#/stop/odd-even-rules|learn"},"story-odd-even-rules-open":{"id":"story-odd-even-rules-open","kind":"story","src":"story:odd-even-rules#open","badge":{"id":"story","label":"A story"},"title":"Partners for the dance","body":"37 children from one school and 58 from another meet in the hall for a partner dance. Will everyone have a partner? — with Rafi and Dax.","more":"The trick inside: Only whether each number is odd or even matters. Even ± even and odd ± odd are even; odd ± even is odd. A product is even if any number in it is even.","art":"art/s-hall.webp","cta":"Read the story","where":"The Prime Quarry · Level 3","level":3,"route":"#/stop/odd-even-rules|story|0"},"hook-odd-even-rules-hook":{"id":"hook-odd-even-rules-hook","kind":"hook","src":"stop:odd-even-rules#hook","title":"Can you? — Odd and even rules","body":"37 + 58 — odd or even? Answer before you add.","more":"The way in: Only whether each number is odd or even matters. Even ± even and odd ± odd are even; odd ± even is odd. A product is even if any number in it is even.","cta":"Find out how","where":"The Prime Quarry · Level 3","level":3,"route":"#/stop/odd-even-rules|learn"},"idea-odd-even-rules-case0":{"id":"idea-odd-even-rules-case0","kind":"idea","src":"stop:odd-even-rules#case0","title":"Odd and even rules: Odd + even","body":"Only the one lonely extra from the odd number is left without a partner, so the answer is odd.","more":"The method: Only whether each number is odd or even matters. Even ± even and odd ± odd are even; odd ± even is odd. A product is even if any number in it is even.","cta":"See it worked","where":"The Prime Quarry · Level 3","level":3,"route":"#/stop/odd-even-rules|learn|0"},"worked-odd-even-rules-worked0":{"id":"worked-odd-even-rules-worked0","kind":"worked","src":"stop:odd-even-rules#worked0","title":"Worked out — Odd and even rules: Odd + even","body":"37 + 58 — odd or even?: Is 37 odd or even? Look at its last digit → odd · And 58? → even · odd + even makes → odd","more":"What is special here: Only the one lonely extra from the odd number is left without a partner, so the answer is odd.","cta":"Watch it step by step","where":"The Prime Quarry · Level 3","level":3,"route":"#/stop/odd-even-rules|learn|0"},"idea-odd-even-rules-case1":{"id":"idea-odd-even-rules-case1","kind":"idea","src":"stop:odd-even-rules#case1","title":"Odd and even rules: Odd + odd","body":"Each odd number has one lonely extra — and the two lonely ones pair up with each other. So the answer is even.","more":"The method: Only whether each number is odd or even matters. Even ± even and odd ± odd are even; odd ± even is odd. A product is even if any number in it is even.","cta":"See it worked","where":"The Prime Quarry · Level 3","level":3,"route":"#/stop/odd-even-rules|learn|1"},"worked-odd-even-rules-worked1":{"id":"worked-odd-even-rules-worked1","kind":"worked","src":"stop:odd-even-rules#worked1","title":"Worked out — Odd and even rules: Odd + odd","body":"23 + 15 — odd or even?: Is 23 odd or even? Look at its last digit → odd · And 15? → odd · odd + odd makes → even","more":"What is special here: Each odd number has one lonely extra — and the two lonely ones pair up with each other. So the answer is even.","cta":"Watch it step by step","where":"The Prime Quarry · Level 3","level":3,"route":"#/stop/odd-even-rules|learn|1"},"idea-odd-even-rules-case2":{"id":"idea-odd-even-rules-case2","kind":"idea","src":"stop:odd-even-rules#case2","title":"Odd and even rules: Even ± even","body":"All pairs and no extras on either side, so nothing can be left over — even. Taking away works just like adding.","more":"The method: Only whether each number is odd or even matters. Even ± even and odd ± odd are even; odd ± even is odd. A product is even if any number in it is even.","cta":"See it worked","where":"The Prime Quarry · Level 3","level":3,"route":"#/stop/odd-even-rules|learn|2"},"worked-odd-even-rules-worked2":{"id":"worked-odd-even-rules-worked2","kind":"worked","src":"stop:odd-even-rules#worked2","title":"Worked out — Odd and even rules: Even ± even","body":"40 − 16 — odd or even?: Is 40 odd or even? Look at its last digit → even · And 16? → even · even − even makes → even","more":"What is special here: All pairs and no extras on either side, so nothing can be left over — even. Taking away works just like adding.","cta":"Watch it step by step","where":"The Prime Quarry · Level 3","level":3,"route":"#/stop/odd-even-rules|learn|2"},"idea-odd-even-rules-case3":{"id":"idea-odd-even-rules-case3","kind":"idea","src":"stop:odd-even-rules#case3","title":"Odd and even rules: Times, with an even","body":"One even number is enough: 37 × 58 is 37 groups of 58, and every group is all pairs. So the answer is even.","more":"The method: Only whether each number is odd or even matters. Even ± even and odd ± odd are even; odd ± even is odd. A product is even if any number in it is even.","cta":"See it worked","where":"The Prime Quarry · Level 3","level":3,"route":"#/stop/odd-even-rules|learn|3"},"idea-odd-even-rules-case4":{"id":"idea-odd-even-rules-case4","kind":"idea","src":"stop:odd-even-rules#case4","title":"Odd and even rules: Odd × odd","body":"The only way a product is odd: every number in it is odd. An odd number of odd groups never pairs up.","more":"The method: Only whether each number is odd or even matters. Even ± even and odd ± odd are even; odd ± even is odd. A product is even if any number in it is even.","cta":"See it worked","where":"The Prime Quarry · Level 3","level":3,"route":"#/stop/odd-even-rules|learn|4"},"worked-odd-even-rules-worked4":{"id":"worked-odd-even-rules-worked4","kind":"worked","src":"stop:odd-even-rules#worked4","title":"Worked out — Odd and even rules: Odd × odd","body":"7 × 9 — odd or even?: Is 7 odd or even? Look at its last digit → odd · And 9? → odd · odd × odd makes → odd","more":"What is special here: The only way a product is odd: every number in it is odd. An odd number of odd groups never pairs up.","cta":"Watch it step by step","where":"The Prime Quarry · Level 3","level":3,"route":"#/stop/odd-even-rules|learn|4"},"why-odd-even-rules-why1":{"id":"why-odd-even-rules-why1","kind":"why","src":"stop:odd-even-rules#why1","title":"Why “Odd and even rules” works","body":"Put the two groups together and the pairs stay pairs. Only the lonely ones matter: odd + even has one lonely child, so the total is odd. Odd + odd has two lonely children — and they pair up with each other, so the total is even. Taking away works the same way.","more":"The trick: Only whether each number is odd or even matters. Even ± even and odd ± odd are even; odd ± even is odd. A product is even if any number in it is even.","cta":"See why","where":"The Prime Quarry · Level 3","level":3,"route":"#/stop/odd-even-rules|learn"},"why-odd-even-rules-why2":{"id":"why-odd-even-rules-why2","kind":"why","src":"stop:odd-even-rules#why2","title":"Why “Odd and even rules” works","body":"For times, 37 × 58 is 37 groups of 58, and every group of 58 is all pairs, so the whole lot is pairs: even. The only way a product is odd is if every number in it is odd — then you have an odd number of odd groups, and the lonely ones never all pair up. And you only ever need the LAST digit to tell odd from even.","more":"The trick: Only whether each number is odd or even matters. Even ± even and odd ± odd are even; odd ± even is odd. A product is even if any number in it is even.","cta":"See why","where":"The Prime Quarry · Level 3","level":3,"route":"#/stop/odd-even-rules|learn"},"algebra-odd-even-rules-alg":{"id":"algebra-odd-even-rules-alg","kind":"algebra","src":"stop:odd-even-rules#alg","title":"The algebra behind “Odd and even rules”","body":"even ± even = even · odd ± odd = even · odd ± even = odd · odd × odd = odd, anything × even = even","more":"In words: Only whether each number is odd or even matters. Even ± even and odd ± odd are even; odd ± even is odd. A product is even if any number in it is even.","cta":"See why","where":"The Prime Quarry · Level 3","level":3,"route":"#/stop/odd-even-rules|learn"},"moment-odd-even-rules-beat3":{"id":"moment-odd-even-rules-beat3","kind":"moment","src":"story:odd-even-rules#beat3","badge":{"id":"story","label":"A story"},"title":"Partners for the dance — on the notepad","body":"Rafi: 37 is 18 pairs and one child on their own. 18 × 2 + 1 = 37","more":"The trick in the story: Only whether each number is odd or even matters. Even ± even and odd ± odd are even; odd ± even is odd. A product is even if any number in it is even.","cta":"Read the story","where":"The Prime Quarry · Level 3","level":3,"route":"#/stop/odd-even-rules|story|3"},"moral-odd-even-rules-beat5":{"id":"moral-odd-even-rules-beat5","kind":"moral","src":"story:odd-even-rules#beat5","badge":{"id":"story","label":"A story"},"title":"Rafi, in “Partners for the dance”","body":"And if both groups were odd, the two lonely ones would dance with each other.","more":"The trick in the story: Only whether each number is odd or even matters. Even ± even and odd ± odd are even; odd ± even is odd. A product is even if any number in it is even.","cta":"Read the story","where":"The Prime Quarry · Level 3","level":3,"route":"#/stop/odd-even-rules|story|5"},"try-odd-even-rules-L3":{"id":"try-odd-even-rules-L3","kind":"try","level":3,"src":"try:odd-even-rules@3/1#0","title":"Odd and even rules — your turn","where":"The Prime Quarry · Level 3","route":"#/stop/odd-even-rules|drill","cta":"Practise this stop","play":{"q":"12 + 19 — odd or even?","opts":["odd","even"],"after":"Only whether each number is odd or even matters. Even ± even and odd ± odd are even; odd ± even is odd. A product is even if any number in it is even."}},"trick-nikhilam-10-idea":{"id":"trick-nikhilam-10-idea","kind":"trick","src":"stop:nikhilam-10#idea","title":"Near ten: the cross","body":"Find how far each number is below 10. Cross-subtract for the tens; multiply the gaps for the ones. 8 is 2 below 10, and 7 is 3 below. Take 3 from 8 (or 2 from 7 — the same, always): 5 tens. Multiply the gaps: 2 × 3 = 6 ones. So 56.","more":"In algebra: (10 − x)(10 − y) = 10(10 − x − y) + xy","cta":"Learn the trick","where":"The Sutra Observatory · Level 3","level":3,"route":"#/stop/nikhilam-10|learn"},"story-nikhilam-10-open":{"id":"story-nikhilam-10-open","kind":"story","src":"story:nikhilam-10#open","badge":{"id":"story","label":"A story"},"title":"The lantern crates","body":"Pip is stacking 8 crates for the night fair. Each crate holds 7 lanterns. — with Kwame and Pip.","more":"The trick inside: Find how far each number is below 10. Cross-subtract for the tens; multiply the gaps for the ones.","art":"art/s-night.webp","cta":"Read the story","where":"The Sutra Observatory · Level 3","level":3,"route":"#/stop/nikhilam-10|story|0"},"idea-nikhilam-10-case0":{"id":"idea-nikhilam-10-case0","kind":"idea","src":"stop:nikhilam-10#case0","title":"Near ten: the cross: The gaps make the ones","body":"The gaps multiply to less than 10, so their product is simply the ones digit.","more":"The method: Find how far each number is below 10. Cross-subtract for the tens; multiply the gaps for the ones.","cta":"See it worked","where":"The Sutra Observatory · Level 3","level":3,"route":"#/stop/nikhilam-10|learn|0"},"idea-nikhilam-10-case1":{"id":"idea-nikhilam-10-case1","kind":"idea","src":"stop:nikhilam-10#case1","title":"Near ten: the cross: The gaps make 10 or more","body":"Now the gaps multiply to 10 or more. Do not squeeze two digits into the ones place — add them on: 3 tens and 12 is 42.","more":"The method: Find how far each number is below 10. Cross-subtract for the tens; multiply the gaps for the ones.","cta":"See it worked","where":"The Sutra Observatory · Level 3","level":3,"route":"#/stop/nikhilam-10|learn|1"},"why-nikhilam-10-why1":{"id":"why-nikhilam-10-why1","kind":"why","src":"stop:nikhilam-10#why1","title":"Why “Near ten: the cross” works","body":"If the gaps multiply to 10 or more, carry: 6 × 7 → gaps 4 and 3, 6 − 3 = 3 tens, 4 × 3 = 12 ones, and 30 + 12 = 42.","more":"The trick: Find how far each number is below 10. Cross-subtract for the tens; multiply the gaps for the ones.","cta":"See why","where":"The Sutra Observatory · Level 3","level":3,"route":"#/stop/nikhilam-10|learn"},"algebra-nikhilam-10-alg":{"id":"algebra-nikhilam-10-alg","kind":"algebra","src":"stop:nikhilam-10#alg","title":"The algebra behind “Near ten: the cross”","body":"(10 − x)(10 − y) = 10(10 − x − y) + xy","more":"In words: Find how far each number is below 10. Cross-subtract for the tens; multiply the gaps for the ones.","cta":"See why","where":"The Sutra Observatory · Level 3","level":3,"route":"#/stop/nikhilam-10|learn"},"moment-nikhilam-10-beat3":{"id":"moment-nikhilam-10-beat3","kind":"moment","src":"story:nikhilam-10#beat3","badge":{"id":"story","label":"A story"},"title":"The lantern crates — on the notepad","body":"Kwame: Cross over: take the other number’s gap from 8. That gives the tens. 8 − 3 = 5","more":"The trick in the story: Find how far each number is below 10. Cross-subtract for the tens; multiply the gaps for the ones.","cta":"Read the story","where":"The Sutra Observatory · Level 3","level":3,"route":"#/stop/nikhilam-10|story|3"},"try-nikhilam-10-L3":{"id":"try-nikhilam-10-L3","kind":"try","level":3,"src":"try:nikhilam-10@3/1#0","title":"Near ten: the cross — your turn","where":"The Sutra Observatory · Level 3","route":"#/stop/nikhilam-10|drill","cta":"Practise this stop","play":{"q":"8 × 7 = ?","opts":["56","2","3"],"after":"Find how far each number is below 10. Cross-subtract for the tens; multiply the gaps for the ones."}},"word-acute-angle":{"id":"word-acute-angle","kind":"word","src":"dictionary:acute angle#def","title":"acute angle","body":"A turn smaller than 90°. For example: 35°.","more":"Taught at: Kinds of angle.","where":"Shape City","route":"#/lib/dictionary|acute angle","cta":"acute angle in the Dictionary","level":3},"wordq-acute-angle":{"id":"wordq-acute-angle","kind":"wordq","src":"dictionary:acute angle#ex","title":"Which maths word?","route":"#/lib/dictionary|acute angle","cta":"Look it up","play":{"q":"Which word is this an example of? “35°.”","opts":["acute angle","share in a ratio","intercept"],"after":"acute angle: A turn smaller than 90°."},"level":3},"word-angle":{"id":"word-angle","kind":"word","src":"dictionary:angle#def","title":"angle","body":"The amount of turn between two lines that meet at a point, measured in degrees. For example: A quarter turn is 90°.","more":"Taught at: Kinds of angle.","where":"Shape City","route":"#/lib/dictionary|angle","cta":"angle in the Dictionary","level":3},"wordq-angle":{"id":"wordq-angle","kind":"wordq","src":"dictionary:angle#ex","title":"Which maths word?","route":"#/lib/dictionary|angle","cta":"Look it up","play":{"q":"Which word is this an example of? “A quarter turn is 90°.”","opts":["angle","surface area","mental maths"],"after":"angle: The amount of turn between two lines that meet at a point, measured in degrees."},"level":3},"word-capacity":{"id":"word-capacity","kind":"word","src":"dictionary:capacity#def","title":"capacity","body":"How much a container can hold. For example: A jug that holds 2 litres.","more":"Taught at: Metres, grams and litres.","where":"The Clock Tower","route":"#/lib/dictionary|capacity","cta":"capacity in the Dictionary","level":3},"wordq-capacity":{"id":"wordq-capacity","kind":"wordq","src":"dictionary:capacity#ex","title":"Which maths word?","route":"#/lib/dictionary|capacity","cta":"Look it up","play":{"q":"Which word is this an example of? “A jug that holds 2 litres.”","opts":["capacity","halve","index laws"],"after":"capacity: How much a container can hold."},"level":3},"word-centimetre":{"id":"word-centimetre","kind":"word","src":"dictionary:centimetre#def","title":"centimetre","body":"One hundredth of a metre — about the width of a fingernail. For example: 10 mm = 1 cm.","more":"Taught at: Metres, grams and litres.","where":"The Clock Tower","route":"#/lib/dictionary|centimetre","cta":"centimetre in the Dictionary","level":3},"wordq-centimetre":{"id":"wordq-centimetre","kind":"wordq","src":"dictionary:centimetre#ex","title":"Which maths word?","route":"#/lib/dictionary|centimetre","cta":"Look it up","play":{"q":"Which word is this an example of? “10 mm = 1 cm.”","opts":["centimetre","isosceles triangle","lowest common multiple"],"after":"centimetre: One hundredth of a metre — about the width of a fingernail."},"level":3},"word-common-denominator":{"id":"word-common-denominator","kind":"word","src":"dictionary:common denominator#def","title":"common denominator","body":"A bottom number that two fractions can both be rewritten over, so they can be added or compared. For example: 1/3 + 1/4 = 4/12 + 3/12 = 7/12.","more":"Taught at: Adding different-sized slices · Which slice is bigger?.","where":"The Fraction Bakery","route":"#/lib/dictionary|common denominator","cta":"common denominator in the Dictionary","level":3},"wordq-common-denominator":{"id":"wordq-common-denominator","kind":"wordq","src":"dictionary:common denominator#ex","title":"Which maths word?","route":"#/lib/dictionary|common denominator","cta":"Look it up","play":{"q":"Which word is this an example of? “1/3 + 1/4 = 4/12 + 3/12 = 7/12.”","opts":["common denominator","origin","estimate"],"after":"common denominator: A bottom number that two fractions can both be rewritten over, so they can be added or compared."},"level":3},"word-convert":{"id":"word-convert","kind":"word","src":"dictionary:convert#def","title":"convert","body":"Change a measurement into a different unit without changing its size. For example: 2.5 km = 2,500 m.","more":"Taught at: Metres, grams and litres.","where":"The Clock Tower","route":"#/lib/dictionary|convert","cta":"convert in the Dictionary","level":3},"wordq-convert":{"id":"wordq-convert","kind":"wordq","src":"dictionary:convert#ex","title":"Which maths word?","route":"#/lib/dictionary|convert","cta":"Look it up","play":{"q":"Which word is this an example of? “2.5 km = 2,500 m.”","opts":["convert","rotation","recurring decimal"],"after":"convert: Change a measurement into a different unit without changing its size."},"level":3},"word-cube":{"id":"word-cube","kind":"word","src":"dictionary:cube#def","title":"cube","body":"A solid with six square faces, all the same size. For example: 12 edges and 8 vertices.","more":"Taught at: Faces, edges and corners · Volume and surface area.","where":"Shape City","route":"#/lib/dictionary|cube","cta":"cube in the Dictionary","level":3},"wordq-cube":{"id":"wordq-cube","kind":"wordq","src":"dictionary:cube#ex","title":"Which maths word?","route":"#/lib/dictionary|cube","cta":"Look it up","play":{"q":"Which word is this an example of? “12 edges and 8 vertices.”","opts":["cube","substitute","recurring decimal"],"after":"cube: A solid with six square faces, all the same size."},"level":3},"word-cylinder":{"id":"word-cylinder","kind":"word","src":"dictionary:cylinder#def","title":"cylinder","body":"A solid with two equal circles at its ends and one curved face joining them. For example: A tin 7 cm across and 11 cm tall.","more":"Taught at: Faces, edges and corners.","where":"Shape City","route":"#/lib/dictionary|cylinder","cta":"cylinder in the Dictionary","level":3},"wordq-cylinder":{"id":"wordq-cylinder","kind":"wordq","src":"dictionary:cylinder#ex","title":"Which maths word?","route":"#/lib/dictionary|cylinder","cta":"Look it up","play":{"q":"Which word is this an example of? “A tin 7 cm across and 11 cm tall.”","opts":["cylinder","hundredth","recurring decimal"],"after":"cylinder: A solid with two equal circles at its ends and one curved face joining them."},"level":3},"word-degree":{"id":"word-degree","kind":"word","src":"dictionary:degree#def","title":"degree","body":"The unit for measuring turn; a full turn is 360 of them. Sign: °. For example: A right angle is 90°.","more":"Taught at: Kinds of angle.","where":"Shape City","route":"#/lib/dictionary|degree","cta":"degree in the Dictionary","level":3},"wordq-degree":{"id":"wordq-degree","kind":"wordq","src":"dictionary:degree#ex","title":"Which maths word?","route":"#/lib/dictionary|degree","cta":"Look it up","play":{"q":"Which word is this an example of? “A right angle is 90°.”","opts":["degree","odd","variable"],"after":"degree: The unit for measuring turn; a full turn is 360 of them. Sign: °."},"level":3},"word-distributive":{"id":"word-distributive","kind":"word","src":"dictionary:distributive#def","title":"distributive","body":"Multiplying a whole bracket gives the same as multiplying each part inside it and adding. For example: 6 × 14 = 6 × 10 + 6 × 4 = 84.","more":"Taught at: Split and multiply · Split the hard one.","where":"The Mental Workshop","route":"#/lib/dictionary|distributive","cta":"distributive in the Dictionary","level":3},"wordq-distributive":{"id":"wordq-distributive","kind":"wordq","src":"dictionary:distributive#ex","title":"Which maths word?","route":"#/lib/dictionary|distributive","cta":"Look it up","play":{"q":"Which word is this an example of? “6 × 14 = 6 × 10 + 6 × 4 = 84.”","opts":["distributive","reciprocal","term"],"after":"distributive: Multiplying a whole bracket gives the same as multiplying each part inside it and adding."},"level":3},"word-divisibility-test":{"id":"word-divisibility-test","kind":"word","src":"dictionary:divisibility test#def","title":"divisibility test","body":"A quick check that tells you whether one number goes exactly into another without doing the sum. For example: Digits adding to a multiple of 3 means 3 goes in: 123 → 1 + 2 + 3 = 6, so yes.","more":"Taught at: Tests for 2, 5 and 10 · Tests for 4 and 8 · Tests for 6 and 11 · Divisible by 3 or 9?.","where":"The Factor Forest","route":"#/lib/dictionary|divisibility test","cta":"divisibility test in the Dictionary","level":3},"wordq-divisibility-test":{"id":"wordq-divisibility-test","kind":"wordq","src":"dictionary:divisibility test#ex","title":"Which maths word?","route":"#/lib/dictionary|divisibility test","cta":"Look it up","play":{"q":"Which word is this an example of? “Digits adding to a multiple of 3 means 3 goes in: 123 → 1 + 2 + 3 = 6, so yes.”","opts":["divisibility test","unitary method","function machine"],"after":"divisibility test: A quick check that tells you whether one number goes exactly into another without doing the sum."},"level":3},"word-divisible":{"id":"word-divisible","kind":"word","src":"dictionary:divisible#def","title":"divisible","body":"Able to be divided exactly, with nothing left over. For example: 42 ÷ 7 = 6 exactly, so 42 is — by 7.","more":"Taught at: Tests for 2, 5 and 10.","where":"The Factor Forest","route":"#/lib/dictionary|divisible","cta":"divisible in the Dictionary","level":3},"wordq-divisible":{"id":"wordq-divisible","kind":"wordq","src":"dictionary:divisible#ex","title":"Which maths word?","route":"#/lib/dictionary|divisible","cta":"Look it up","play":{"q":"Which word is this an example of? “42 ÷ 7 = 6 exactly, so 42 is — by 7.”","opts":["divisible","protractor","circumference"],"after":"divisible: Able to be divided exactly, with nothing left over."},"level":3},"word-duration":{"id":"word-duration","kind":"word","src":"dictionary:duration#def","title":"duration","body":"How long something lasts, from start to finish. For example: 9:45 to 11:15 lasts 1 hour 30 minutes.","more":"Taught at: How long is it?.","where":"The Clock Tower","route":"#/lib/dictionary|duration","cta":"duration in the Dictionary","level":3},"wordq-duration":{"id":"wordq-duration","kind":"wordq","src":"dictionary:duration#ex","title":"Which maths word?","route":"#/lib/dictionary|duration","cta":"Look it up","play":{"q":"Which word is this an example of? “9:45 to 11:15 lasts 1 hour 30 minutes.”","opts":["duration","combination","cuboid"],"after":"duration: How long something lasts, from start to finish."},"level":3},"word-edge":{"id":"word-edge","kind":"word","src":"dictionary:edge#def","title":"edge","body":"A line where two faces of a solid meet. For example: A cube has 12.","more":"Taught at: Faces, edges and corners.","where":"Shape City","route":"#/lib/dictionary|edge","cta":"edge in the Dictionary","level":3},"wordq-edge":{"id":"wordq-edge","kind":"wordq","src":"dictionary:edge#ex","title":"Which maths word?","route":"#/lib/dictionary|edge","cta":"Look it up","play":{"q":"Which word is this an example of? “A cube has 12.”","opts":["edge","percentage change","even chance"],"after":"edge: A line where two faces of a solid meet."},"level":3},"word-equivalent-fractions":{"id":"word-equivalent-fractions","kind":"word","src":"dictionary:equivalent fractions#def","title":"equivalent fractions","body":"Fractions that look different but stand for the same amount. For example: 1/2 = 2/4 = 3/6.","more":"Taught at: Same share, different pieces.","where":"The Fraction Bakery","route":"#/lib/dictionary|equivalent fractions","cta":"equivalent fractions in the Dictionary","level":3},"word-eulers-formula":{"id":"word-eulers-formula","kind":"word","src":"dictionary:Euler’s formula#def","title":"Euler’s formula","body":"For any solid with flat faces and no holes: faces + vertices − edges = 2. For example: A cube: 6 + 8 − 12 = 2.","more":"Taught at: Faces, edges and corners.","where":"Shape City","route":"#/lib/dictionary|Euler’s formula","cta":"Euler’s formula in the Dictionary","level":3},"wordq-eulers-formula":{"id":"wordq-eulers-formula","kind":"wordq","src":"dictionary:Euler’s formula#ex","title":"Which maths word?","route":"#/lib/dictionary|Euler’s formula","cta":"Look it up","play":{"q":"Which word is this an example of? “A cube: 6 + 8 − 12 = 2.”","opts":["Euler’s formula","mass","decimal place"],"after":"Euler’s formula: For any solid with flat faces and no holes: faces + vertices − edges = 2."},"level":3},"word-even":{"id":"word-even","kind":"word","src":"dictionary:even#def","title":"even","body":"Able to be split into two equal whole groups; the last digit is 0, 2, 4, 6 or 8. For example: 36 = 18 + 18.","more":"Taught at: Tests for 2, 5 and 10.","where":"The Factor Forest","route":"#/lib/dictionary|even","cta":"even in the Dictionary","level":3},"wordq-even":{"id":"wordq-even","kind":"wordq","src":"dictionary:even#ex","title":"Which maths word?","route":"#/lib/dictionary|even","cta":"Look it up","play":{"q":"Which word is this an example of? “36 = 18 + 18.”","opts":["even","volume","denominator"],"after":"even: Able to be split into two equal whole groups; the last digit is 0, 2, 4, 6 or 8."},"level":3},"word-expand":{"id":"word-expand","kind":"word","src":"dictionary:expand#def","title":"expand","body":"Multiply out brackets. For example: 3(x + 2) = 3x + 6.","more":"Taught at: Split and multiply.","where":"The Mental Workshop","route":"#/lib/dictionary|expand","cta":"expand in the Dictionary","level":3},"wordq-expand":{"id":"wordq-expand","kind":"wordq","src":"dictionary:expand#ex","title":"Which maths word?","route":"#/lib/dictionary|expand","cta":"Look it up","play":{"q":"Which word is this an example of? “3(x + 2) = 3x + 6.”","opts":["expand","parallelogram","rate"],"after":"expand: Multiply out brackets."},"level":3},"word-face":{"id":"word-face","kind":"word","src":"dictionary:face#def","title":"face","body":"A flat surface of a solid. For example: A cube has 6, all squares.","more":"Taught at: Faces, edges and corners.","where":"Shape City","route":"#/lib/dictionary|face","cta":"face in the Dictionary","level":3},"wordq-face":{"id":"wordq-face","kind":"wordq","src":"dictionary:face#ex","title":"Which maths word?","route":"#/lib/dictionary|face","cta":"Look it up","play":{"q":"Which word is this an example of? “A cube has 6, all squares.”","opts":["face","numerator","duration"],"after":"face: A flat surface of a solid."},"level":3},"word-gram":{"id":"word-gram","kind":"word","src":"dictionary:gram#def","title":"gram","body":"A small unit of mass; a paperclip weighs about 1. For example: 1,000 g = 1 kg.","more":"Taught at: Metres, grams and litres.","where":"The Clock Tower","route":"#/lib/dictionary|gram","cta":"gram in the Dictionary","level":3},"wordq-gram":{"id":"wordq-gram","kind":"wordq","src":"dictionary:gram#ex","title":"Which maths word?","route":"#/lib/dictionary|gram","cta":"Look it up","play":{"q":"Which word is this an example of? “1,000 g = 1 kg.”","opts":["gram","identity","function machine"],"after":"gram: A small unit of mass; a paperclip weighs about 1."},"level":3},"word-kilometre":{"id":"word-kilometre","kind":"word","src":"dictionary:kilometre#def","title":"kilometre","body":"One thousand metres. For example: A 5 km run is 5,000 m.","more":"Taught at: Metres, grams and litres.","where":"The Clock Tower","route":"#/lib/dictionary|kilometre","cta":"kilometre in the Dictionary","level":3},"wordq-kilometre":{"id":"wordq-kilometre","kind":"wordq","src":"dictionary:kilometre#ex","title":"Which maths word?","route":"#/lib/dictionary|kilometre","cta":"Look it up","play":{"q":"Which word is this an example of? “A 5 km run is 5,000 m.”","opts":["kilometre","difference","division"],"after":"kilometre: One thousand metres."},"level":3},"word-litre":{"id":"word-litre","kind":"word","src":"dictionary:litre#def","title":"litre","body":"The main unit of capacity in the system built on tens — a big bottle of water. For example: 1,000 ml = 1 l.","more":"Taught at: Metres, grams and litres.","where":"The Clock Tower","route":"#/lib/dictionary|litre","cta":"litre in the Dictionary","level":3},"wordq-litre":{"id":"wordq-litre","kind":"wordq","src":"dictionary:litre#ex","title":"Which maths word?","route":"#/lib/dictionary|litre","cta":"Look it up","play":{"q":"Which word is this an example of? “1,000 ml = 1 l.”","opts":["litre","average","circle"],"after":"litre: The main unit of capacity in the system built on tens — a big bottle of water."},"level":3},"word-mass":{"id":"word-mass","kind":"word","src":"dictionary:mass#def","title":"mass","body":"How heavy something is — how much stuff it is made of — measured in grams and kilograms. For example: A bag of sugar: 1 kg.","more":"Taught at: Metres, grams and litres.","where":"The Clock Tower","route":"#/lib/dictionary|mass","cta":"mass in the Dictionary","level":3},"wordq-mass":{"id":"wordq-mass","kind":"wordq","src":"dictionary:mass#ex","title":"Which maths word?","route":"#/lib/dictionary|mass","cta":"Look it up","play":{"q":"Which word is this an example of? “A bag of sugar: 1 kg.”","opts":["mass","odd","per cent"],"after":"mass: How heavy something is — how much stuff it is made of — measured in grams and kilograms."},"level":3},"word-metre":{"id":"word-metre","kind":"word","src":"dictionary:metre#def","title":"metre","body":"The main unit of length in the system built on tens — roughly one long adult stride. For example: 100 cm = 1 m.","more":"Taught at: Metres, grams and litres.","where":"The Clock Tower","route":"#/lib/dictionary|metre","cta":"metre in the Dictionary","level":3},"wordq-metre":{"id":"wordq-metre","kind":"wordq","src":"dictionary:metre#ex","title":"Which maths word?","route":"#/lib/dictionary|metre","cta":"Look it up","play":{"q":"Which word is this an example of? “100 cm = 1 m.”","opts":["metre","simple interest","rounding"],"after":"metre: The main unit of length in the system built on tens — roughly one long adult stride."},"level":3},"word-metric":{"id":"word-metric","kind":"word","src":"dictionary:metric#def","title":"metric","body":"Built on tens, hundreds and thousands, like metres, grams and litres. For example: 1 km = 1,000 m.","more":"Taught at: Metres, grams and litres.","where":"The Clock Tower","route":"#/lib/dictionary|metric","cta":"metric in the Dictionary","level":3},"wordq-metric":{"id":"wordq-metric","kind":"wordq","src":"dictionary:metric#ex","title":"Which maths word?","route":"#/lib/dictionary|metric","cta":"Look it up","play":{"q":"Which word is this an example of? “1 km = 1,000 m.”","opts":["metric","division","equivalent fractions"],"after":"metric: Built on tens, hundreds and thousands, like metres, grams and litres."},"level":3},"word-multiple":{"id":"word-multiple","kind":"word","src":"dictionary:multiple#def","title":"multiple","body":"What you get when a number is multiplied by 1, 2, 3, 4 and so on — its times table, carried on for ever. For example: 6, 12, 18 and 24 are the first four for 6.","more":"Taught at: The next multiple.","where":"The Factor Forest","route":"#/lib/dictionary|multiple","cta":"multiple in the Dictionary","level":3},"wordq-multiple":{"id":"wordq-multiple","kind":"wordq","src":"dictionary:multiple#ex","title":"Which maths word?","route":"#/lib/dictionary|multiple","cta":"Look it up","play":{"q":"Which word is this an example of? “6, 12, 18 and 24 are the first four for 6.”","opts":["multiple","average","permutation"],"after":"multiple: What you get when a number is multiplied by 1, 2, 3, 4 and so on — its times table, carried on for ever."},"level":3},"word-net":{"id":"word-net","kind":"word","src":"dictionary:net#def","title":"net","body":"A flat pattern that folds up to make a solid. For example: 6 squares in a cross fold into a cube.","more":"Taught at: Faces, edges and corners.","where":"Shape City","route":"#/lib/dictionary|net","cta":"net in the Dictionary","level":3},"wordq-net":{"id":"wordq-net","kind":"wordq","src":"dictionary:net#ex","title":"Which maths word?","route":"#/lib/dictionary|net","cta":"Look it up","play":{"q":"Which word is this an example of? “6 squares in a cross fold into a cube.”","opts":["net","nth term","less than"],"after":"net: A flat pattern that folds up to make a solid."},"level":3},"word-obtuse-angle":{"id":"word-obtuse-angle","kind":"word","src":"dictionary:obtuse angle#def","title":"obtuse angle","body":"A turn bigger than 90° but smaller than 180°. For example: 125°.","more":"Taught at: Kinds of angle.","where":"Shape City","route":"#/lib/dictionary|obtuse angle","cta":"obtuse angle in the Dictionary","level":3},"wordq-obtuse-angle":{"id":"wordq-obtuse-angle","kind":"wordq","src":"dictionary:obtuse angle#ex","title":"Which maths word?","route":"#/lib/dictionary|obtuse angle","cta":"Look it up","play":{"q":"Which word is this an example of? “125°.”","opts":["obtuse angle","half","base"],"after":"obtuse angle: A turn bigger than 90° but smaller than 180°."},"level":3},"word-odd":{"id":"word-odd","kind":"word","src":"dictionary:odd#def","title":"odd","body":"Leaving one over when split into twos; the last digit is 1, 3, 5, 7 or 9. For example: 37 = 18 + 18 + 1.","more":"Taught at: Tests for 2, 5 and 10 · The odd-number staircase.","where":"The Factor Forest","route":"#/lib/dictionary|odd","cta":"odd in the Dictionary","level":3},"wordq-odd":{"id":"wordq-odd","kind":"wordq","src":"dictionary:odd#ex","title":"Which maths word?","route":"#/lib/dictionary|odd","cta":"Look it up","play":{"q":"Which word is this an example of? “37 = 18 + 18 + 1.”","opts":["odd","sutra","product"],"after":"odd: Leaving one over when split into twos; the last digit is 1, 3, 5, 7 or 9."},"level":3},"word-perimeter":{"id":"word-perimeter","kind":"word","src":"dictionary:perimeter#def","title":"perimeter","body":"The distance all the way round the edge of a flat shape. For example: 6 cm by 4 cm: 6 + 4 + 6 + 4 = 20 cm.","more":"Taught at: Perimeter.","where":"The Clock Tower","route":"#/lib/dictionary|perimeter","cta":"perimeter in the Dictionary","level":3},"wordq-perimeter":{"id":"wordq-perimeter","kind":"wordq","src":"dictionary:perimeter#ex","title":"Which maths word?","route":"#/lib/dictionary|perimeter","cta":"Look it up","play":{"q":"Which word is this an example of? “6 cm by 4 cm: 6 + 4 + 6 + 4 = 20 cm.”","opts":["perimeter","cuboid","Vedic maths"],"after":"perimeter: The distance all the way round the edge of a flat shape."},"level":3},"word-perpendicular":{"id":"word-perpendicular","kind":"word","src":"dictionary:perpendicular#def","title":"perpendicular","body":"Meeting or crossing at a right angle. For example: The 2 sides at the corner of a page meet at 90°.","more":"Taught at: Kinds of angle.","where":"Shape City","route":"#/lib/dictionary|perpendicular","cta":"perpendicular in the Dictionary","level":3},"wordq-perpendicular":{"id":"wordq-perpendicular","kind":"wordq","src":"dictionary:perpendicular#ex","title":"Which maths word?","route":"#/lib/dictionary|perpendicular","cta":"Look it up","play":{"q":"Which word is this an example of? “The 2 sides at the corner of a page meet at 90°.”","opts":["perpendicular","centimetre","denominator"],"after":"perpendicular: Meeting or crossing at a right angle."},"level":3},"word-prism":{"id":"word-prism","kind":"word","src":"dictionary:prism#def","title":"prism","body":"A solid with the same cross-section all the way along its length. For example: A triangular one has 5 faces, like a tent.","more":"Taught at: Faces, edges and corners.","where":"Shape City","route":"#/lib/dictionary|prism","cta":"prism in the Dictionary","level":3},"wordq-prism":{"id":"wordq-prism","kind":"wordq","src":"dictionary:prism#ex","title":"Which maths word?","route":"#/lib/dictionary|prism","cta":"Look it up","play":{"q":"Which word is this an example of? “A triangular one has 5 faces, like a tent.”","opts":["prism","sequence","inequality"],"after":"prism: A solid with the same cross-section all the way along its length."},"level":3},"word-protractor":{"id":"word-protractor","kind":"word","src":"dictionary:protractor#def","title":"protractor","body":"A see-through half-circle marked in degrees, for measuring and drawing turns. For example: Line the centre up with the corner, read 0 along one arm.","more":"Taught at: Kinds of angle.","where":"Shape City","route":"#/lib/dictionary|protractor","cta":"protractor in the Dictionary","level":3},"wordq-protractor":{"id":"wordq-protractor","kind":"wordq","src":"dictionary:protractor#ex","title":"Which maths word?","route":"#/lib/dictionary|protractor","cta":"Look it up","play":{"q":"Which word is this an example of? “Line the centre up with the corner, read 0 along one arm.”","opts":["protractor","percentage","working backwards"],"after":"protractor: A see-through half-circle marked in degrees, for measuring and drawing turns."},"level":3},"word-pyramid":{"id":"word-pyramid","kind":"word","src":"dictionary:pyramid#def","title":"pyramid","body":"A solid with a flat base and triangular faces that meet at one point on top. For example: A square-based one has 5 faces.","more":"Taught at: Faces, edges and corners.","where":"Shape City","route":"#/lib/dictionary|pyramid","cta":"pyramid in the Dictionary","level":3},"wordq-pyramid":{"id":"wordq-pyramid","kind":"wordq","src":"dictionary:pyramid#ex","title":"Which maths word?","route":"#/lib/dictionary|pyramid","cta":"Look it up","play":{"q":"Which word is this an example of? “A square-based one has 5 faces.”","opts":["pyramid","casting out nines","identity"],"after":"pyramid: A solid with a flat base and triangular faces that meet at one point on top."},"level":3},"word-reflex-angle":{"id":"word-reflex-angle","kind":"word","src":"dictionary:reflex angle#def","title":"reflex angle","body":"A turn bigger than 180° but smaller than 360°. For example: 250°.","more":"Taught at: Kinds of angle.","where":"Shape City","route":"#/lib/dictionary|reflex angle","cta":"reflex angle in the Dictionary","level":3},"wordq-reflex-angle":{"id":"wordq-reflex-angle","kind":"wordq","src":"dictionary:reflex angle#ex","title":"Which maths word?","route":"#/lib/dictionary|reflex angle","cta":"Look it up","play":{"q":"Which word is this an example of? “250°.”","opts":["reflex angle","associative","power"],"after":"reflex angle: A turn bigger than 180° but smaller than 360°."},"level":3},"word-right-angle":{"id":"word-right-angle","kind":"word","src":"dictionary:right angle#def","title":"right angle","body":"A quarter turn: exactly 90°. For example: The corner of a page: 90°.","more":"Taught at: Kinds of angle.","where":"Shape City","route":"#/lib/dictionary|right angle","cta":"right angle in the Dictionary","level":3},"wordq-right-angle":{"id":"wordq-right-angle","kind":"wordq","src":"dictionary:right angle#ex","title":"Which maths word?","route":"#/lib/dictionary|right angle","cta":"Look it up","play":{"q":"Which word is this an example of? “The corner of a page: 90°.”","opts":["right angle","variable","odd"],"after":"right angle: A quarter turn: exactly 90°."},"level":3},"word-roman-numerals":{"id":"word-roman-numerals","kind":"word","src":"dictionary:Roman numerals#def","title":"Roman numerals","body":"Numbers written with the letters I, V, X, L, C, D and M, added or taken away depending on where they sit. For example: XIV = 10 + 4 = 14.","more":"Taught at: Roman numerals.","where":"The Number Library","route":"#/lib/dictionary|Roman numerals","cta":"Roman numerals in the Dictionary","level":3},"wordq-roman-numerals":{"id":"wordq-roman-numerals","kind":"wordq","src":"dictionary:Roman numerals#ex","title":"Which maths word?","route":"#/lib/dictionary|Roman numerals","cta":"Look it up","play":{"q":"Which word is this an example of? “XIV = 10 + 4 = 14.”","opts":["Roman numerals","union","compound shape"],"after":"Roman numerals: Numbers written with the letters I, V, X, L, C, D and M, added or taken away depending on where they sit."},"level":3},"formula-perimeter-rectangle":{"id":"formula-perimeter-rectangle","kind":"formula","src":"formula:perimeter-rectangle","title":"Perimeter of a rectangle","body":"P = 2 × (l + w). One long side and one short side take you exactly half-way round.","more":"Taught at: Perimeter.","where":"The Clock Tower","route":"#/lib/formulas|perimeter-rectangle","cta":"Perimeter of a rectangle in the Formula Book","play":{"q":"Perimeter of a rectangle: A rectangle 7 cm long and 4 cm wide.","opts":["22","23","21"],"after":"l + w = 7 + 4 = 11 · P = 2 × 11 = 22 cm"},"level":3},"formula-why-perimeter-rectangle-0":{"id":"formula-why-perimeter-rectangle-0","kind":"formula-why","src":"formula:perimeter-rectangle#why0","title":"Why P = 2 × (l + w)","body":"Walk once round a rectangle and you go along a long side, a short side, a long side and a short side. The two long sides are equal, and so are the two short ones.","more":"The card: Perimeter of a rectangle — One long side and one short side take you exactly half-way round.","route":"#/lib/formulas|perimeter-rectangle","cta":"Perimeter of a rectangle in the Formula Book","level":3},"formula-why-perimeter-rectangle-1":{"id":"formula-why-perimeter-rectangle-1","kind":"formula-why","src":"formula:perimeter-rectangle#why1","title":"Why P = 2 × (l + w)","body":"So one long side and one short side take you exactly half-way round. Add them, then double: P = 2 × (l + w). It is the same as l + w + l + w — just quicker.","more":"The card: Perimeter of a rectangle — One long side and one short side take you exactly half-way round.","route":"#/lib/formulas|perimeter-rectangle","cta":"Perimeter of a rectangle in the Formula Book","level":3},"formula-story-perimeter-rectangle":{"id":"formula-story-perimeter-rectangle","kind":"formula-story","src":"formula:perimeter-rectangle#story","badge":{"id":"story","label":"A story"},"title":"Fencing the vegetable patch","body":"Nova’s vegetable patch is a rectangle 9 metres long and 5 metres wide. Pip has to buy the fence. — with Nova and Pip.","art":"art/s-garden.webp","route":"#/lib/formulas|perimeter-rectangle","cta":"Perimeter of a rectangle in the Formula Book","level":3},"formula-try-perimeter-rectangle":{"id":"formula-try-perimeter-rectangle","kind":"formula-try","src":"formula:perimeter-rectangle#gen0","title":"Perimeter of a rectangle — your turn","route":"#/lib/formulas|perimeter-rectangle","cta":"Perimeter of a rectangle in the Formula Book","play":{"q":"Perimeter of a rectangle 10 cm by 7 cm (in cm) = ?","opts":["34","35","33"],"after":"P = 2 × (l + w)"},"level":3},"formula-euler":{"id":"formula-euler","kind":"formula","src":"formula:euler","title":"Euler’s formula for solids","body":"F + V − E = 2. Faces plus corners take away edges: 2, for every solid like these.","more":"Taught at: Faces, edges and corners.","where":"Shape City","route":"#/lib/formulas|euler","cta":"Euler’s formula for solids in the Formula Book","play":{"q":"Euler’s formula for solids: A cube has 6 faces and 8 corners. How many edges?","opts":["12","13","11"],"after":"E = F + V − 2 · = 6 + 8 − 2 = 12 edges"},"level":3},"formula-why-euler-0":{"id":"formula-why-euler-0","kind":"formula-why","src":"formula:euler#why0","title":"Why F + V − E = 2","body":"Count the faces F, corners V and edges E of any solid with flat faces and no hole through it. Add the faces and the corners, take away the edges, and you always get 2.","more":"The card: Euler’s formula for solids — Faces plus corners take away edges: 2, for every solid like these.","route":"#/lib/formulas|euler","cta":"Euler’s formula for solids in the Formula Book","level":3},"formula-why-euler-1":{"id":"formula-why-euler-1","kind":"formula-why","src":"formula:euler#why1","title":"Why F + V − E = 2","body":"Here is a hint of why it cannot move. Slice one corner off a cube: you gain 1 new face and 3 new edges, and the 1 old corner becomes 3 new ones. F + V − E changes by 1 + 2 − 3 = 0. It carries the name of Leonhard Euler, who wrote about it.","more":"The card: Euler’s formula for solids — Faces plus corners take away edges: 2, for every solid like these.","route":"#/lib/formulas|euler","cta":"Euler’s formula for solids in the Formula Book","level":3},"formula-story-euler":{"id":"formula-story-euler","kind":"formula-story","src":"formula:euler#story","badge":{"id":"story","label":"A story"},"title":"The chocolate box","body":"Suki’s chocolate box is a triangular prism. Rafi counts 5 faces and 6 corners, then loses count of the edges. — with Rafi and Suki.","art":"art/s-shop.webp","route":"#/lib/formulas|euler","cta":"Euler’s formula for solids in the Formula Book","level":3},"formula-try-euler":{"id":"formula-try-euler","kind":"formula-try","src":"formula:euler#gen0","title":"Euler’s formula for solids — your turn","route":"#/lib/formulas|euler","cta":"Euler’s formula for solids in the Formula Book","play":{"q":"A tetrahedron (triangle-based pyramid) has 4 corners and 6 edges. How many faces?","opts":["4","5","3"],"after":"F + V − E = 2"},"level":3},"formula-square-of-sum":{"id":"formula-square-of-sum","kind":"formula","src":"formula:square-of-sum","title":"Squaring a sum","body":"(a + b)² = a² + 2ab + b². A square of side a + b is a², b² and two a × b strips.","more":"Taught at: The next square up · Split and multiply.","where":"The Number Harbour","route":"#/lib/formulas|square-of-sum","cta":"Squaring a sum in the Formula Book","play":{"q":"Squaring a sum: 34², as (30 + 4)².","opts":["1156","1157","1155"],"after":"30² = 900, 2 × 30 × 4 = 240, 4² = 16 · 900 + 240 + 16 = 1156"},"level":3},"formula-why-square-of-sum-0":{"id":"formula-why-square-of-sum-0","kind":"formula-why","src":"formula:square-of-sum#why0","title":"Why (a + b)² = a² + 2ab + b²","body":"Draw a square with sides a + b and cut each side where a ends. The big square splits into four pieces: an a by a square, a b by b square, and two a by b rectangles.","more":"The card: Squaring a sum — A square of side a + b is a², b² and two a × b strips.","route":"#/lib/formulas|square-of-sum","cta":"Squaring a sum in the Formula Book","level":3},"formula-why-square-of-sum-1":{"id":"formula-why-square-of-sum-1","kind":"formula-why","src":"formula:square-of-sum#why1","title":"Why (a + b)² = a² + 2ab + b²","body":"Add the pieces and you have a² + ab + ab + b², which is a² + 2ab + b². That is why 23² = 20² + 2 × 20 × 3 + 3² = 400 + 120 + 9 = 529.","more":"The card: Squaring a sum — A square of side a + b is a², b² and two a × b strips.","route":"#/lib/formulas|square-of-sum","cta":"Squaring a sum in the Formula Book","level":3},"formula-story-square-of-sum":{"id":"formula-story-square-of-sum","kind":"formula-story","src":"formula:square-of-sum#story","badge":{"id":"story","label":"A story"},"title":"The herb garden grows","body":"Mira’s square herb garden is 20 by 20 tiles. She makes it 3 tiles bigger each way. How many tiles now? — with Mira and Nova.","art":"art/s-garden.webp","route":"#/lib/formulas|square-of-sum","cta":"Squaring a sum in the Formula Book","level":3},"formula-try-square-of-sum":{"id":"formula-try-square-of-sum","kind":"formula-try","src":"formula:square-of-sum#gen0","title":"Squaring a sum — your turn","route":"#/lib/formulas|square-of-sum","cta":"Squaring a sum in the Formula Book","play":{"q":"Use (a + b)²: 33² = (30 + 3)² = ?","opts":["1089","1090","1088"],"after":"(a + b)² = a² + 2ab + b²"},"level":3},"stone-vedic-nikhilam-10":{"src":"journey:vedic/nikhilam-10#0","badge":{"id":"review","label":"Being checked"},"source":"Sources, being checked by a second reader: Bharati Krishna Tirtha, Vedic Mathematics (Motilal Banarsidass, 1965).","route":"#/lib/vedic|nikhilam-10","cta":"Stone 3: All from nine, the last from ten","where":"The Vedic Maths Journey · stone 3 of 13","id":"stone-vedic-nikhilam-10","kind":"stone","title":"All from nine, the last from ten — Nikhilam Navataścaramaṁ Daśataḥ","body":"For two numbers close to 10, look at how far each one is from 10 — its gap.","level":3},"stone-vedic-nikhilam-10-1":{"src":"journey:vedic/nikhilam-10#1","badge":{"id":"review","label":"Being checked"},"source":"Sources, being checked by a second reader: Bharati Krishna Tirtha, Vedic Mathematics (Motilal Banarsidass, 1965).","route":"#/lib/vedic|nikhilam-10","cta":"Stone 3: All from nine, the last from ten","where":"The Vedic Maths Journey · stone 3 of 13","id":"stone-vedic-nikhilam-10-1","kind":"stone-step","title":"All from nine, the last from ten (2 of 4)","body":"Cross: take one number's gap away from the other number. That gives the tens. Then multiply the two gaps: that gives the units. 8 × 7: gaps 2 and 3. 8 − 3 = 5 tens; 2 × 3 = 6. Answer 56.","level":3},"stone-vedic-nikhilam-10-2":{"src":"journey:vedic/nikhilam-10#2","badge":{"id":"review","label":"Being checked"},"source":"Sources, being checked by a second reader: Bharati Krishna Tirtha, Vedic Mathematics (Motilal Banarsidass, 1965).","route":"#/lib/vedic|nikhilam-10","cta":"Stone 3: All from nine, the last from ten","where":"The Vedic Maths Journey · stone 3 of 13","id":"stone-vedic-nikhilam-10-2","kind":"stone-step","title":"All from nine, the last from ten (3 of 4)","body":"Why: (10 − x)(10 − y) = 10(10 − x − y) + xy. The cross, 10 − x − y, is the same whichever way you do it. If the gaps multiply to more than 9, the extra ten carries across.","level":3},"stone-vedic-nikhilam-10-3":{"src":"journey:vedic/nikhilam-10#3","badge":{"id":"review","label":"Being checked"},"source":"Sources, being checked by a second reader: Bharati Krishna Tirtha, Vedic Mathematics (Motilal Banarsidass, 1965).","route":"#/lib/vedic|nikhilam-10","cta":"Stone 3: All from nine, the last from ten","where":"The Vedic Maths Journey · stone 3 of 13","id":"stone-vedic-nikhilam-10-3","kind":"stone-step","title":"All from nine, the last from ten (4 of 4)","body":"Above 10 works too — just add the gap instead: 12 × 13 is 12 + 3 = 15 tens, and 2 × 3 = 6, so 156.","level":3},"stone-try-vedic-nikhilam-10":{"src":"journey:vedic/nikhilam-10#gen0","badge":{"id":"review","label":"Being checked"},"source":"Sources, being checked by a second reader: Bharati Krishna Tirtha, Vedic Mathematics (Motilal Banarsidass, 1965).","route":"#/lib/vedic|nikhilam-10","cta":"Stone 3: All from nine, the last from ten","where":"The Vedic Maths Journey · stone 3 of 13","id":"stone-try-vedic-nikhilam-10","kind":"stone-try","title":"All from nine, the last from ten — try it","play":{"q":"5 × 5 = ?","opts":["25","5","0"],"after":"Multiplying near 10"},"level":3}};
